    id: "broker",
    zh: "消息代理",
    en: "Message Broker",
    area: "foundation",
    difficulty: "easy",
    concept: "Broker 是消息系统的中枢，负责接收消息、路由消息、暂存消息、分发消息和维护连接状态。",
    explanation: [
      "核心概念：消息代理（Message Broker）是生产者和消费者之间的中间层。生产者把消息交给 Broker，Broker 根据交换机、绑定和队列规则完成投递，消费者从 Broker 获取消息并确认处理结果。",
      "主流程：客户端先建立 Connection，再在 Channel 上声明交换机、队列和绑定；生产者发布消息到交换机；Broker 路由到队列；消费者订阅队列；消费者 Ack 后 Broker 删除对应消息。",
      "职责边界：Broker 负责协议接入、资源声明、路由决策、队列存储、投递调度、确认状态和权限校验。业务语义、消息幂等、事务一致性和失败补偿主要由应用侧设计承担。",
      "可靠性能力：Broker 可以通过持久化队列、持久化消息、Publisher Confirm、Consumer Ack、死信交换机、仲裁队列和镜像/集群能力增强可靠性。可靠投递通常需要生产端、Broker 和消费端三段一起设计。",
      "资源与性能：Broker 的吞吐受连接数、通道数、队列数量、消息大小、磁盘写入、内存水位、消费者速度和确认模式影响。队列过长会增加内存和磁盘压力，也会拖慢恢复和迁移。",
      "监控重点：运行中重点看 queue depth、messages ready、messages unacked、publish/deliver/ack 速率、连接数、通道数、消费者数、磁盘水位、内存水位和节点告警。Management Plugin 和监控接口可以暴露这些状态。",
      "特殊情况：消费者处理成功但 Ack 发送失败时，消息可能重新投递；生产者收到确认前连接断开时，需要按消息 id 或业务幂等处理重发；路由规则缺失时，消息会成为不可路由消息。",
      "常见误区：Broker 能保证消息系统的基础投递语义，端到端业务正确性还要依赖幂等、重试、死信、补偿和一致性方案。把所有可靠性都压给 Broker，会让异常场景缺少业务闭环。",
      "参考来源：Broker 和 AMQP 模型参考 RabbitMQ documentation 与 AMQP concepts；路由参考 Exchanges；队列存储参考 Queues；确认机制参考 Confirms；运行观测参考 Management Plugin 与 Monitoring；中文资料参考 JavaGuide。",
    ],
