    id: "virtual-host",
    zh: "虚拟主机",
    en: "Virtual Host",
    area: "foundation",
    difficulty: "easy",
    concept: "Virtual Host 是 RabbitMQ 的逻辑命名空间，用来隔离交换机、队列、绑定、权限和运行指标。",
    explanation: [
      "核心概念：虚拟主机（Virtual Host，vhost）是 RabbitMQ Broker 内的资源隔离空间。每个 vhost 都有独立的交换机、队列、绑定和权限配置，适合把不同环境、业务线或租户隔开。",
      "资源范围：交换机名、队列名和绑定关系都属于某个 vhost。两个 vhost 里可以出现同名队列或交换机，它们代表不同资源；客户端连接时要指定目标 vhost，后续声明和发布都发生在这个 vhost 内。",
      "权限模型：RabbitMQ 用户需要被授予某个 vhost 的 configure、write、read 权限，才可以声明资源、发布消息或消费消息。权限通常用正则匹配资源名，适合按业务前缀做最小权限控制。",
      "连接边界：一个 AMQP 连接属于一个 vhost。应用要在两个 vhost 之间搬运消息时，通常需要分别连接两个 vhost，并在应用层或桥接组件里完成转发。",
      "适用场景：vhost 常用于 dev/test/prod 环境隔离、多团队共享集群、多租户资源隔离和权限边界管理。它能减少资源命名冲突，也能让管理后台按 vhost 查看队列、连接和消息速率。",
      "特殊情况：vhost 是逻辑隔离，底层 CPU、内存、磁盘和网络仍由同一个 Broker 或集群共享。某个 vhost 队列堆积、磁盘报警或连接暴涨，仍可能影响同节点上的其他 vhost。",
      "运维建议：为 vhost 制定命名规范、资源前缀、用户权限模板和配额策略；监控时按 vhost 观察队列深度、未确认消息、连接数、消费者数和消息速率。删除 vhost 前要确认其中资源和消息都已迁移或清理。",
      "常见误区：vhost 提供的是 RabbitMQ 内部命名空间和权限边界，业务级隔离还需要配合独立账号、资源限制、告警、容量规划和变更审批。",
      "参考来源：vhost 定义、连接边界和资源范围参考 RabbitMQ Virtual Hosts；权限模型参考 Access Control；AMQP 模型参考 AMQP concepts；交换机和队列范围参考 Exchanges、Queues；运行查看参考 Management Plugin 和 Monitoring；中文资料参考 JavaGuide。",
    ],
