    concept: "连接是客户端与 RabbitMQ Broker 之间的 TCP 长连接，负责认证、绑定 vhost，并承载多个 Channel。",
    explanation: [
      "核心概念：RabbitMQ Connection 是客户端和 Broker 之间的网络连接，通常建立在 TCP 之上，也可以启用 TLS。应用先建立连接、完成认证并选择 vhost，再在连接上创建 Channel 进行发布、消费和确认。",
      "生命周期：连接建立后会协商协议、认证用户、选择 vhost、协商心跳和连接参数。业务运行期间，连接应长期复用；发布、消费、声明资源这些操作通过 Channel 完成。",
      "Channel 复用：一个连接可以承载多个 Channel，Channel 是 AMQP 的轻量会话。常见实践是少量连接配合多个 Channel，减少 TCP 握手、TLS 握手、文件描述符和内存开销。",
      "心跳机制：Heartbeats 用来发现半开连接、网络中断和长时间无响应。心跳间隔过低会增加误判概率，过高会延迟故障发现；客户端和服务端应使用一致且适合网络环境的配置。",
      "资源成本：每个连接都会消耗 Broker 端内存、文件描述符、Erlang 进程和网络资源。连接频繁创建关闭会造成 churn，吞吐高时还会放大 CPU 和 TLS 成本。",
      "适用场景：连接用于应用接入 RabbitMQ、连接池管理、多 vhost 接入和发布/消费链路隔离。生产者和消费者可以使用不同连接，关键业务也可以用独立连接隔离故障影响。",
      "特殊情况：一个连接属于一个 vhost，跨 vhost 访问需要建立对应 vhost 的连接。连接断开会关闭其上的 Channel，未确认投递可能重新入队，未确认发布需要生产者按确认序列和业务幂等处理。",
      "排查指标：连接数持续上涨通常指向连接泄漏或重连风暴；连接 churn 高通常指向短连接使用、网络抖动或客户端自动重连配置异常。排查时看 connection count、channel count、client properties、state、recv/send rate、心跳超时和服务端日志。",
      "参考来源：连接生命周期和复用建议参考 RabbitMQ Connections；Channel 模型参考 Channels；心跳参考 Heartbeats；网络监听和 TLS 参考 Networking；资源限制参考 Configurable Limits；认证和 vhost 权限参考 Access Control；运行观察参考 Management Plugin 和 Monitoring；中文资料参考 JavaGuide。",
    ],
