    id: "heartbeat",
    zh: "心跳",
    en: "Heartbeat",
    area: "foundation",
    difficulty: "easy",
    concept: "心跳是 AMQP 连接上的轻量保活机制，用来更快发现断开的 TCP 连接和无响应的对端。",
    explanation: [
      "核心概念：RabbitMQ Heartbeat 用于在应用层发现断开的 TCP 连接。操作系统默认检测断连可能很慢，心跳让客户端和 Broker 更快知道对端失联，并触发关闭连接和重连流程。",
      "协商机制：连接建立时，服务端给出心跳 timeout，客户端也给出期望值，双方协商出最终值。RabbitMQ 默认建议值是 60 秒，客户端需要主动配置或接受该值。",
      "发送规则：心跳帧大约每 `timeout / 2` 秒发送一次。连续两次心跳缺失后，对端会被认为不可达，TCP 连接会被关闭。普通 AMQP 流量、发布消息、确认帧等也可以算作有效心跳活动。",
      "参数选择：官方经验建议多数环境使用 5-20 秒范围。值太低容易因为短暂网络拥塞、服务端流控或调度抖动产生误判；值太高会延迟故障发现。生产环境通常从 30 或 60 秒起步，再结合网络质量调优。",
      "代理场景：负载均衡器、防火墙和代理可能关闭空闲 TCP 连接。开启心跳会产生周期性轻量流量，能降低空闲连接被提前关闭的概率；跨云、跨机房和 Kubernetes Service 场景尤其要关注。",
      "关闭风险：双方都设置 0 才会关闭心跳。关闭心跳会让断连发现依赖 TCP keepalive，默认 TCP keepalive 通常很慢；需要关闭时，应先确保所有节点和客户端都有合适的 TCP keepalive 配置。",
      "故障处理：心跳超时后客户端要重连、重新打开 Channel、重新声明拓扑、恢复消费者订阅，并处理未确认消息。生产者还要结合 Publisher Confirm 和业务幂等处理未知状态的消息。",
      "排查路径：看到 missed heartbeats、connection reset、frequent reconnects 时，先看客户端和服务端日志，再查有效 heartbeat timeout、连接来源、网络丢包、代理空闲超时、节点流控和连接 churn。",
      "参考来源：心跳目的、协商、默认值、推荐范围、误判风险、心跳帧和 TCP keepalive 参考 RabbitMQ Heartbeats；连接生命周期参考 Connections；网络和代理场景参考 Networking；确认与恢复影响参考 Confirms、Consumers；运行观察参考 Management Plugin 和 Monitoring。",
    ],
