    id: "message",
    zh: "消息",
    en: "Message",
    area: "foundation",
    difficulty: "easy",
    concept: "消息由 payload/body、properties 和投递元数据组成，承载业务内容、路由辅助信息和可靠性语义。",
    explanation: [
      "核心概念：RabbitMQ 中的 Message 是生产者发布、Broker 路由、队列保存、消费者处理的基本单位。它通常包含 payload/body、message properties 和 delivery metadata。",
      "消息体：payload/body 是业务数据本身，RabbitMQ 不理解业务语义，只把它当作字节序列传递。JSON、Protobuf、Avro 或文本格式都可以使用，编码和兼容性由应用约定。",
      "属性字段：message properties 描述消息元信息，常见字段有 content_type、content_encoding、headers、delivery_mode、priority、correlation_id、reply_to、expiration、message_id、timestamp、type、user_id、app_id。",
      "投递元数据：delivery metadata 与一次投递相关，例如 exchange、routing key、redelivered 标记和 delivery tag。delivery tag 用于消费者在 Channel 上确认消息，redelivered 可辅助识别重新投递。",
      "可靠性语义：关键消息通常要配合持久化队列、delivery_mode=2、Publisher Confirm 和手动 Ack。单独设置消息持久化只覆盖消息写入持久化路径，端到端可靠还需要处理发布失败、消费失败和重复投递。",
      "过期控制：消息可以通过 per-message TTL（expiration 属性）或队列 TTL 过期。过期消息会被丢弃或进入死信交换机，适合限时任务、延迟重试和过期通知。",
      "特殊情况：消息过大、headers 过多或批量堆积会放大内存、磁盘和网络压力；属性里可能包含敏感业务字段，日志和监控输出要脱敏；message_id 通常由业务生成，适合做幂等键和审计线索。",
      "设计建议：先定义消息 schema、版本字段、message_id、correlation_id、事件类型、过期策略和幂等规则，再决定持久化、确认和死信策略。消费者应把消息解析失败、版本兼容和重复投递作为标准分支处理。",
      "参考来源：消息组成、properties 和 delivery metadata 参考 RabbitMQ Publishers；AMQP 模型参考 AMQP concepts；发布确认和消费确认参考 Confirms；TTL 参考 Time-To-Live and Expiration；持久化参考 Persistence Configuration；队列保存和资源边界参考 Queues、Configurable Limits；中文资料参考 JavaGuide。",
    ],
