    id: "message-properties",
    zh: "消息属性",
    en: "Message Properties",
    area: "foundation",
    difficulty: "medium",
    concept: "消息属性是生产者随消息设置的元数据，用来描述内容格式、持久化、过期、追踪、幂等和业务类型。",
    explanation: [
      "核心概念：Message Properties 是消息体之外的元数据，由生产者在发布时设置。它们帮助消费者理解 payload，也让 Broker 根据部分字段执行持久化、过期和校验等行为。",
      "常见字段：`content_type` 描述消息格式，`content_encoding` 描述编码或压缩，`headers` 放自定义键值，`delivery_mode` 控制瞬态或持久化，`priority` 表示优先级，`correlation_id` 关联请求响应，`reply_to` 指定响应队列，`expiration` 设置 per-message TTL，`message_id` 支持幂等和追踪，`timestamp`、`type`、`user_id`、`app_id` 提供审计和分类信息。",
      "投递信息边界：`delivery tag`、`redelivered`、`exchange`、`routing key`、`consumer tag` 是投递时由 RabbitMQ 或协议上下文提供的信息，属于 delivery metadata。它们常和 properties 一起出现在客户端回调里，设计时要分清来源。",
      "业务语义：RabbitMQ 不解析业务 payload，也通常不校验 `content_type`、`type`、`message_id` 的业务含义。生产者和消费者需要约定 schema、版本、事件类型和兼容策略。",
      "可靠性字段：`delivery_mode=2` 表示消息走持久化语义，仍要配合持久化队列和 Publisher Confirm。`expiration` 控制消息过期，过期后会被丢弃或进入死信交换机，适合限时消息和重试延迟。",
      "追踪与幂等：`message_id` 适合做去重键，`correlation_id` 适合串联一次业务请求或 RPC 响应，`headers` 可携带 trace id、tenant id、schema version。消费者要把这些字段纳入日志和幂等存储。",
      "特殊情况：headers 体积过大、属性过多或携带敏感字段，会增加内存、网络和日志风险。消息跨语言传递时，要确认客户端库对属性类型、大小写、时间戳和枚举值的映射方式。",
      "设计建议：属性命名保持稳定，业务字段优先放 payload，路由、追踪、幂等、版本和过期控制放 properties。发布端写属性前先定义规范，消费端遇到未知 type 或 schema version 要记录并进入兼容处理流程。",
      "参考来源：消息属性列表、delivery metadata 和协议差异参考 RabbitMQ Publishers；AMQP 模型参考 AMQP concepts；TTL 参考 Time-To-Live and Expiration；持久化参考 Persistence Configuration；确认语义参考 Confirms；队列与优先级边界参考 Queues；中文资料参考 JavaGuide。",
    ],
