    id: "consumer",
    zh: "消费者",
    en: "Consumer",
    area: "foundation",
    difficulty: "easy",
    concept: "消费者从队列订阅并处理消息，通过 Ack/Nack、prefetch 和幂等逻辑控制消息生命周期与消费速度。",
    explanation: [
      "核心概念：消费者（Consumer）是从队列接收投递并执行业务处理的应用实例或订阅。RabbitMQ 通常把消息推送给已注册的长生命周期消费者，消费者处理后通过确认机制告诉 Broker 结果。",
      "消费流程：应用建立 Connection、打开 Channel、注册 Consumer；队列有 ready 消息时开始投递；业务处理成功后发送 Ack；处理失败时发送 Nack/Reject，并选择重新入队或进入死信流程。",
      "长生命周期：消费者适合在应用启动时注册并长期运行。`basic.get` 这种逐条拉取属于轮询模式，在队列长期为空或流量不稳定时效率低，官方更建议使用长期订阅的消费者。",
      "确认模式：自动确认会在投递后立即让 Broker 认为消息完成，适合容忍丢失的场景。手动确认把删除时机交给业务代码，适合数据库写入、外部接口调用和关键业务消息。",
      "预取控制：prefetch 限制单个消费者或 Channel 上未确认消息数量。它能避免慢消费者一次拿走太多消息，也能影响吞吐和分发公平性；CPU 密集、I/O 密集和长耗时任务需要不同取值。",
      "重复投递：连接断开、Channel 关闭、消费者超时、Nack/requeue 和 Broker 恢复都可能导致消息重新投递。消费者要用 message_id 或业务唯一键做幂等，并把业务成功与 Ack 顺序设计清楚。",
      "超时边界：RabbitMQ 有消费确认超时保护，默认 30 分钟。消费者在超时时间内未确认投递，Channel 会被关闭，相关未确认投递会重新入队；长任务应拆分、延长超时或改成任务状态机。",
      "恢复流程：连接丢失后，客户端要重连、重建 Channel、重新声明队列/交换机/绑定并重新注册 Consumer。自动恢复库能覆盖常见场景，业务仍要处理重复消息和处理中的任务状态。",
      "排查指标：消费问题重点看 messages ready、messages unacked、consumer count、consumer capacity、deliver/ack rate、prefetch、redelivered rate、consumer utilisation、连接重连和应用处理耗时。ready 增长通常代表消费能力低，unacked 增长通常代表处理慢或 Ack 异常。",
      "参考来源：消费者定义、生命周期、consumer tag、prefetch、确认超时、basic.get 边界和 consumer capacity 参考 RabbitMQ Consumers；Ack/Nack 语义参考 Confirms；队列投递参考 Queues；连接、Channel、心跳和恢复参考 Connections、Channels、Heartbeats；监控指标参考 Monitoring；中文资料参考 JavaGuide。",
    ],
