    id: "exchange",
    zh: "交换机",
    en: "Exchange",
    area: "exchange",
    difficulty: "easy",
    concept: "交换机接收生产者发布的消息，并按交换机类型、路由键和绑定规则把消息路由到队列、流或其他交换机。",
    explanation: [
      "核心概念：Exchange 是 RabbitMQ 的路由表入口。生产者把消息发布到 Exchange，Exchange 根据自身类型和 Binding 规则，把消息路由到一个或多个 Queue、Stream 或另一个 Exchange。",
      "vhost 范围：每个 Exchange 都属于一个 Virtual Host。不同 vhost 可以有同名 Exchange；客户端发布时使用当前连接绑定的 vhost 内的 Exchange。",
      "四种常见类型：Direct 按 routing key 与 binding key 精确匹配；Fanout 把消息复制到所有绑定目标并忽略 routing key；Topic 用 `*` 和 `#` 通配符匹配分段 routing key；Headers 根据消息 headers 和绑定参数匹配。",
      "默认交换机：默认交换机是预声明的 direct exchange，AMQP 0-9-1 发布时用空字符串 `\"\"` 作为名称。队列声明后会自动以队列名作为 routing key 绑定到默认交换机，所以可以用队列名直接发布。",
      "绑定规则：Exchange 刚声明时是一张空路由表，需要通过 Binding 把它和队列、流或另一个交换机连接起来。Binding 可以包含 binding key 和 arguments，Headers 交换机会使用 arguments 进行匹配。",
      "不可路由消息：消息找不到任何匹配绑定时，会成为不可路由消息。可以用 mandatory 返回给生产者，也可以配置 Alternate Exchange 接收这些消息，用于路由兜底、拓扑迁移和异常消息收集。",
      "持久化与自动删除：Exchange 可以是 durable 或 transient，也可以 auto-delete。业务交换机通常使用 durable；transient 交换机和半持久绑定在节点停止、重连和大拓扑恢复时更容易产生复杂路由状态。",
      "扩展能力：RabbitMQ 支持 Exchange-to-Exchange Binding，把源交换机路由结果扩展到目标交换机；插件还能提供一致性哈希、随机、本地随机等交换机类型，用于特殊分发场景。",
      "设计建议：先从业务语义选择 Exchange 类型，再设计 routing key 命名规范、binding 规则、AE/mandatory 兜底、交换机持久化和权限边界。发布确认只能说明 Broker 对发布进行了确认，消息是否进入目标队列还要结合路由规则和返回/AE 策略判断。",
      "参考来源：Exchange 定义、类型、默认交换机、绑定、持久化、可选参数和 E2E Binding 参考 RabbitMQ Exchanges；AMQP 模型参考 AMQP concepts；生产者发布参考 Publishers；队列目标参考 Queues；不可路由兜底参考 Alternate Exchanges；确认语义参考 Confirms；中文资料参考 JavaGuide。",
    ],
