    id: "direct-exchange",
    zh: "Direct 交换机",
    en: "Direct Exchange",
    area: "exchange",
    difficulty: "easy",
    concept: "Direct 交换机按 routing key 与 binding key 的精确相等关系路由消息，适合明确类型或状态的点对点分发。",
    explanation: [
      "核心概念：Direct Exchange 使用精确匹配规则路由消息。生产者发布消息时携带 routing key，队列绑定交换机时设置 binding key；两者完全相等时，消息会投递到该绑定目标。",
      "匹配规则：binding key `abc` 只匹配 routing key `abc`。大小写、分隔符、前后缀都按普通字符串处理，没有 Topic 交换机里的 `*`、`#` 通配符语义。",
      "多目标投递：多个队列可以用同一个 binding key 绑定到同一个 Direct Exchange。此时一条消息会复制到所有匹配队列，形成按键广播；一个队列也可以用多个 binding key 绑定同一个交换机，订阅多类消息。",
      "默认交换机：RabbitMQ 默认交换机是一个特殊的 Direct Exchange，名称在发布时写空字符串 `\"\"`。每个队列会自动用队列名作为 routing key 绑定到默认交换机，便于直接按队列名发布。",
      "适用场景：Direct Exchange 适合订单事件按状态路由、任务按优先级或类型路由、日志按级别路由、命令类消息投递到指定业务队列。",
      "不可路由：routing key 找不到任何匹配 binding key 时，消息会成为不可路由消息。关键链路要使用 mandatory 返回或 Alternate Exchange 收集，避免配置错误悄悄吞掉消息。",
      "设计建议：routing key 保持稳定、短小、可枚举，例如 `order.created`、`payment.failed`、`email.send`。当路由规则需要层级通配或按多个字段组合匹配时，Topic 或 Headers Exchange 更合适。",
      "常见误区：Direct Exchange 可以一对一，也可以一对多，取决于匹配绑定数量。它的精确匹配能力很强，路由规则膨胀时会让拓扑维护成本上升，应及时抽象 key 命名和绑定管理。",
      "参考来源：Direct 精确匹配、默认交换机和绑定行为参考 RabbitMQ Exchanges；AMQP 模型参考 AMQP concepts；生产者发布参考 Publishers；队列目标参考 Queues；不可路由兜底参考 Alternate Exchanges；中文资料参考 JavaGuide。",
    ],
