    useCases: ["按租户和版本分发消息", "按文件格式路由任务", "多维事件筛选", "属性驱动的订阅模型"],
    prerequisites: ["exchange", "message-properties"],
    related: ["header-match", "binding", "message-properties", "topic-exchange", "mandatory", "alternate-exchange"],
