      "核心概念：Binding 把 exchange 和 queue 连接起来，也可以把 exchange 和另一个 exchange 连接起来。交换机收到消息后，会遍历自己的绑定表，根据交换机类型、routing key、binding key 和 arguments 计算目标。",
      "主流程：生产者把消息发布到交换机，并携带 routing key 和消息属性；交换机拿这些输入去匹配绑定；匹配成功的绑定会把消息投递到目标队列或下游交换机。同一条消息可以命中多个绑定，形成广播、主题订阅或多路分发。",
      "不同交换机使用绑定的方式不同：Direct 关注 routing key 与 binding key 是否相等；Topic 关注点分 routing key 与通配 binding key 是否匹配；Fanout 只关心是否存在绑定；Headers 关注 binding arguments 与消息 headers 的匹配结果。",
      "绑定键和绑定参数：binding key 是绑定上的一个字符串条件，arguments 是绑定上的扩展参数。Headers Exchange 主要靠 arguments，Topic/Direct 主要靠 binding key；理解这两个字段，才能解释消息为什么进了某个队列。",
      "Exchange-to-Exchange Binding：RabbitMQ 支持把一个交换机绑定到另一个交换机，让上游交换机把命中的消息继续交给下游交换机路由。它适合做分层路由和共享入口，但链路变长后排查成本也会上升。",
      "特殊情况：没有任何绑定命中时，消息会进入不可路由分支，可能触发 `mandatory` 返回或 alternate exchange。持久化交换机和持久化队列之间的绑定通常会随元数据保留；临时队列、自动删除队列或拓扑重建会改变绑定生命周期。",
