      "参考来源：本讲解参考 RabbitMQ AMQP 模型、Exchange、Queue、Exchange-to-Exchange Binding 文档、CloudAMQP 入门文章和 doocs advanced-java，重点采用官方对绑定、绑定键、绑定参数和路由失败分支的定义。",
