      "核心概念：Routing Key 是消息发布请求中的路由属性。生产者把消息发到某个 exchange，并同时给出 routing key；exchange 再结合自己的类型和 bindings 决定消息进入哪些队列。",
      "和 Binding Key 的关系：routing key 来自发布端，binding key 来自订阅端绑定规则。Direct Exchange 做精确相等匹配，Topic Exchange 做分段模式匹配，Fanout Exchange 会忽略 routing key，Headers Exchange 主要使用 headers。",
      "默认交换机：RabbitMQ 预声明了一个名称为空字符串的 direct exchange。每个队列创建后会按队列名自动绑定到默认交换机，所以发布到默认交换机时，把 routing key 写成队列名就能投递到对应队列。",
      "Direct 场景：routing key 适合表达明确事件或任务类别，例如 `order.created`、`email.send`。多个队列使用同一个 binding key 绑定 direct exchange 时，一条匹配消息会复制到这些队列。",
      "Topic 场景：routing key 通常使用点号分段，例如 `order.created.cn.vip`。Topic Exchange 会用队列绑定上的 `*` 和 `#` 模式匹配这些段，适合服务、事件、地区、租户等多维订阅。",
      "命名建议：routing key 要稳定、短小、可读，段位含义要固定。常见形式是 `domain.event` 或 `domain.event.region`；把高基数字段、随机 ID 和敏感信息放进 routing key 会增加绑定数量、监控噪声和泄露风险。",
      "特殊情况：大小写、空格、分段数量、拼写差异都会影响匹配。Topic 的 `#` 会扩大命中范围，Fanout 场景的 routing key 只作为发布参数保留，Headers 场景要重点看 message properties.headers。",
      "排查方法：从发布日志拿到 exchange、routing key、mandatory 标记和 headers，再查看该 exchange 的 bindings。按交换机类型套用匹配规则；未命中时观察 publisher return、alternate exchange 和 broker 的 unroutable 指标。",
