    explanation: [
      "核心概念：Routing Pattern 是一套消息分发设计。生产者把消息发到 exchange，消费者侧通过 queue 和 binding 声明订阅规则，exchange 根据类型和绑定表把消息复制到一个或多个目标队列。",
      "精确路由：Direct Exchange 适合明确类别分发，routing key 与 binding key 精确相等时命中。例如 `order.created` 进入订单创建队列，`email.send` 进入邮件任务队列。",
      "广播路由：Fanout Exchange 适合发布订阅，交换机会把消息复制给所有已绑定队列。它常用于缓存刷新、配置变更、事件通知等需要多个系统同时接收的场景。",
      "主题路由：Topic Exchange 适合层级主题订阅，routing key 用点号分段，binding key 用 `*` 和 `#` 表达订阅范围。它常用于事件总线、日志分流、区域或租户维度筛选。",
      "属性路由：Headers Exchange 适合多属性匹配，交换机读取 message headers，并根据 binding arguments 与 `x-match` 判断命中。多维条件经常变化时，headers 方式更容易表达。",
      "选型方法：单队列任务分发通常用默认 exchange 或 direct；多系统都要收到同一事件用 fanout；按主题层级筛选用 topic；按结构化属性筛选用 headers。复杂系统可以组合多个交换机和 E2E binding 做分层路由。",
      "特殊情况：同一条消息命中多个绑定时会复制到多个队列；同一队列存在多条匹配绑定时，RabbitMQ 会把消息投递到该队列一次。没有任何绑定命中会进入不可路由分支，结合 `mandatory`、publisher return 和 alternate exchange 处理。",
      "排查方法：先确定发布 exchange 和 exchange type，再拿 routing key、headers 与 bindings 对照。Direct 看精确值，Fanout 看绑定存在性，Topic 看分段通配，Headers 看 `x-match` 和 header 值；最后看 return、AE 队列和队列深度。",
      "参考来源：本讲解参考 RabbitMQ AMQP 模型、Exchange、Publisher 文档、CloudAMQP 入门文章和 doocs advanced-java，重点采用官方对交换机类型、bindings、路由失败分支和消息复制语义的定义。",
    ],
