    concept: "不可路由消息是已到达交换机但没有被路由到任何队列的消息。",
    explanation: [
      "核心概念：Unroutable Message 指消息发布到了一个存在的 exchange，exchange 按绑定规则计算后没有找到任何目标队列。它发生在路由阶段，常见原因是没有绑定、binding key 不匹配、Topic 通配模式写错、Headers 条件不满足。",
      "前置区分：发布到不存在的 exchange 会触发 channel-level exception，并关闭当前 channel；不可路由消息的前提是目标 exchange 存在，只是路由结果为空。排查时先把这两个故障阶段分开。",
      "`mandatory=false`：AMQP 0-9-1 默认情况下，消息无法路由到队列时会被丢弃；如果源 exchange 配置了 alternate exchange，RabbitMQ 会把消息交给 AE 继续路由。AE 成功命中队列时，消息进入兜底队列。",
      "`mandatory=true`：消息无法路由到任何队列时，RabbitMQ 会把消息返回给生产者，生产者需要注册 return handler，记录错误、报警或改用其他路由策略。没有 return handler 时，应用层仍然容易丢失这条故障线索。",
      "和发布确认的关系：Publisher Confirm 表示 Broker 接收并处理发布请求的确认，通常关注消息是否到达 Broker；不可路由处理关注消息是否命中队列。关键消息发布要同时开启 confirm、mandatory/return handler，并监控 AE 队列。",
      "工程场景：不可路由消息常出现在新服务上线前绑定未创建、事件名改版、Topic 段位调整、权限导致拓扑声明失败、自动恢复过程中绑定尚未恢复。它适合作为拓扑巡检和发布端回归测试的重点指标。",
      "排查方法：先确认 exchange 是否存在且类型正确，再查看 bindings；拿发布端 exchange、routing key、headers 与 binding key、arguments 对照。接着查看 `unroutable dropped`、`unroutable returned` 指标、publisher return 日志、AE 队列深度和 Broker 告警日志。",
      "处理建议：关键业务消息使用明确的拓扑声明顺序、publisher confirm、mandatory return handler 和 AE 兜底队列；普通通知类消息也要保留指标和采样日志，避免配置漂移长期隐藏。",
      "参考来源：本讲解参考 RabbitMQ Publisher、AMQP 模型、Exchange、Alternate Exchange、Publisher Confirms 文档和 doocs advanced-java，重点采用官方对不可路由、mandatory、AE 和确认机制的定义。",
    ],
