      "适用场景：排他队列适合客户端私有、短生命周期状态，例如 RPC 响应队列、临时回调队列、一次性订阅、测试探测队列。它让资源跟随连接自动清理，避免临时队列长期残留。",
      "命名建议：官方建议排他队列优先使用服务端生成名称。固定名称的排他队列在客户端断线并快速重连时，可能遇到旧队列删除和新连接重建之间的竞争，造成恢复失败或偶发异常。",
      "和 durable 的关系：排他队列天然随连接消亡，声明成 durable 没有清晰语义。生产中把 exclusive 与非持久、服务端命名、短生命周期绑定放在一起理解，会更贴合它的设计目标。",
      "和 auto-delete 的关系：exclusive 按声明连接关闭删除；auto-delete 按最后一个消费者取消或消失删除。排他队列常常也设置 auto-delete，但真正的关键是连接级所有权和连接关闭删除。",
      "队列类型限制：排他队列会按 classic queue 声明。Quorum queue 和 stream 的生命周期依赖复制和持久状态，和单个连接绑定的排他语义不匹配。",
