      "触发条件：auto-delete 关注的是 consumer 消失。典型触发包括 AMQP `basic.cancel`、消费者进程退出、channel 关闭、连接断开和网络故障。删除时，队列里的未消费消息和绑定关系也会随队列一起消失。",
      "关键边界：队列如果从未有过 consumer，auto-delete 不会自动触发。使用 `basic.get` 轮询拉取消息的场景也没有持续 consumer 概念，这类临时队列需要用 exclusive queue 或 queue TTL 做资源清理。",
      "和排他队列的区别：exclusive queue 跟声明连接绑定，连接关闭就删除；auto-delete queue 跟消费者绑定，最后一个消费者离开才删除。一个队列可以同时设置 exclusive 和 auto-delete，但它们观察的生命周期事件不同。",
      "适用场景：自动删除队列适合临时订阅、短生命周期事件监听、UI 或移动端会话、临时广播接收器。它让订阅者离开后自动回收队列，减少手工清理和遗留资源。",
      "命名与恢复风险：使用固定名称的 auto-delete 队列时，客户端连接失败并立刻自动恢复，可能遇到旧连接触发删除和新连接重新声明之间的竞态。官方建议通过连接恢复延迟或服务端生成队列名规避这类问题。",
      "版本与组合：RabbitMQ 4.3 起，非持久且非排他的 classic queue 默认无法声明。临时队列常见选择是非持久排他队列，或 durable queue 搭配 queue TTL。普通业务临时状态要结合版本、队列类型和清理语义选择。",
      "排查方法：队列提前消失，先查 consumer 是否被 cancel、channel/connection 是否关闭、心跳是否超时；队列长期残留，检查是否从未创建过 consumer、是否只用 `basic.get` 轮询、是否声明到了错误 vhost、是否需要 queue TTL。",
