      "工作机制：`x-max-priority` 定义队列支持的最高优先级。消息进入队列后按优先级分层存放，消费者可接收消息时，RabbitMQ 先从高优先级层取 ready 消息；同一优先级内部仍按入队顺序处理。",
      "声明边界：优先级能力属于队列声明参数，队列创建后同名队列再次声明必须保持参数一致，否则会触发属性不一致错误。官方建议优先级级别保持较小范围，常见值是 1 到 10，过多级别会增加 CPU、内存和 Erlang 进程开销。",
      "投递边界：优先级只影响仍在队列中等待投递的 ready 消息。已经发给消费者、处于 unacked 状态的消息会继续占用消费者窗口，所以预取数量过大时，高优先级消息可能被低优先级消息挡住。",
      "使用建议：优先级队列需要搭配合理的 prefetch。官方建议消费者使用 `basic.qos`，并用较小的预取窗口给高优先级消息插队机会；高并发消费者场景要结合业务幂等和重试策略观察最终处理顺序。",
      "适用场景：它适合 VIP 任务、告警通知、补偿任务、人工干预指令、少量高价值消息抢占普通任务。优先级维度越简单越稳定，通常用 3 到 5 档就能表达业务差异。",
      "队列类型限制：优先级队列主要面向 classic queue。Quorum queue 关注复制一致性和高可用语义，选型时要优先判断业务核心需求是优先级投递、复制可靠性还是流式吞吐。",
      "排查方法：高优先级消息没有提前消费，先查队列是否声明了 `x-max-priority`、发布消息是否带 `priority`、priority 是否落在允许范围内、消费者 prefetch 是否过大、低优先级消息是否已经处于 unacked 状态。",
      "参考来源：本讲解参考 RabbitMQ Priority Support、Queues、Consumer Prefetch、Classic Queues、Quorum Queues 和 doocs advanced-java，重点采用官方对 `x-max-priority`、消息 `priority`、资源开销和预取窗口影响的说明。",
