    area: "reliability",
    difficulty: "medium",
    concept: "发布确认让生产者拿到 Broker 对每条发布消息的 ack/nack 结果，从而把未知发布状态转化为可重试、可补偿的状态。",
    explanation: [
      "核心概念：Publisher Confirm 是生产者到 RabbitMQ 的可靠发布确认机制。生产者在 channel 上开启 confirm mode 后，每条发布消息都会获得递增序列号，Broker 处理完成后返回 ack 或 nack。",
      "确认含义：ack 表示 RabbitMQ 已经接收并处理这次发布。对 durable queue 中的 persistent message，ack 通常在消息进入持久化路径后发出；对 quorum queue，ack 表示消息已复制到多数成员。nack 表示 Broker 处理失败，生产者要按业务策略重发或补偿。",
      "批量确认：确认帧带有 delivery tag 和 multiple 标志。multiple 为 true 时，代表该序列号及之前所有未确认消息一起确认。生产者需要维护未确认消息表，按序列号删除或重试。",
      "三种用法：同步逐条等待实现简单但吞吐低；批量等待能提高吞吐但失败定位较粗；异步 confirm listener 吞吐最高，适合生产环境，但需要线程安全地管理未确认消息、超时和重发。",
      "和路由结果的边界：发布确认关注 Broker 是否处理发布请求。消息是否命中队列，还要结合 mandatory return 或 alternate exchange。关键链路通常同时启用 publisher confirm、mandatory return handler、拓扑声明和监控指标。",
      "和事务的关系：confirm mode 是常用的高吞吐可靠发布方案，channel transaction 会显著降低吞吐。需要数据库事务和消息发布一致时，工程上常用事务外盒，再由后台发布器结合 confirm 标记发送状态。",
      "超时与重试：生产者在超时、channel 关闭、连接断开、nack 时会遇到未知状态。重发可能造成重复消息，所以业务消息要带 message_id 或业务唯一键，消费端要做幂等。",
      "排查方法：确认回调迟迟不来，先看 channel 是否开启 confirm mode、连接是否被阻塞、磁盘/内存水位是否报警、持久化写入是否变慢、队列类型是否为 quorum、未确认表是否泄漏。nack 或关闭 channel 时要保留序列号、消息 ID 和 Broker 日志。",
      "参考来源：本讲解参考 RabbitMQ Publisher Confirms、Reliable Publishing 教程、Publishers、Channels、Persistence Configuration 和 doocs advanced-java，重点采用官方对 confirm mode、ack/nack、multiple、持久化确认和异步确认的说明。",
    ],
