    zh: "否定确认",
    en: "Negative Acknowledgement",
    area: "reliability",
    difficulty: "medium",
    concept: "否定确认是消费者主动声明本次投递处理失败的信号，可把消息重新入队或交给死信流程。",
    explanation: [
      "核心概念：Negative Acknowledgement 用于消费失败分支。消费者拿到消息后，如果业务处理失败、下游暂时不可用或消息格式异常，可以发送 `basic.reject` 或 `basic.nack` 告诉 RabbitMQ 这次投递无法正常完成。",
      "`basic.reject`：AMQP 0-9-1 原生命令，一次只能处理一个 delivery tag，适合单条消息失败处理。它带有 requeue 参数，用来决定消息回队列还是进入丢弃/死信分支。",
      "`basic.nack`：RabbitMQ 扩展命令，支持 multiple。multiple 为 true 时，可以一次否定当前 delivery tag 及之前所有未确认投递，适合批量消费者在一批消息失败时统一处理。",
      "requeue=true：RabbitMQ 会尝试把消息放回原队列，位置尽量接近原位置；并发消费者和队列状态变化会影响实际位置。重新投递时 `redelivered` 标记会变为 true，业务应记录重试次数和幂等键。",
      "requeue=false：消息会从当前队列移除。队列配置了 dead-letter exchange 时，消息会进入死信路由；没有 DLX 时会被丢弃。关键业务应把不可恢复失败路由到死信队列，保留排查和人工补偿入口。",
      "重试风险：对同一条消息持续 nack 并 requeue 会形成重投递循环，吞吐被重复失败消息占满，CPU 和网络被浪费。常见治理方式是延迟重试、重试次数上限、死信队列和毒丸消息隔离。",
      "和 prefetch 的关系：prefetch 决定消费者持有的 unacked 数量。大量未确认消息同时 nack/requeue 会造成瞬时重投递压力；批量 nack 前要确认这些消息都适合相同处理策略。",
      "适用场景：下游短暂故障可选择 requeue 或延迟重试；参数错误、无法解析、业务校验永久失败适合进入死信队列；消费者正在优雅停机时，可以 nack 未处理完的消息交给其他实例。",
      "排查方法：redelivered 或 nack rate 持续升高时，检查业务错误类型、requeue 参数、DLX 是否配置、死信路由是否命中、prefetch 是否过大、消费者是否在异常路径重复 nack 同一批消息。",
      "参考来源：本讲解参考 RabbitMQ Negative Acknowledgements、Consumer Acknowledgements、Dead Letter Exchanges、Consumers、Consumer Prefetch 和 doocs advanced-java，重点采用官方对 `basic.reject`、`basic.nack`、multiple、requeue 和死信分流的说明。",
    ],
