    concept: "预取数量通过 `basic.qos` 限制消费者未确认消息窗口，用来控制并发、内存占用和分发公平性。",
    explanation: [
      "预取数量是消费者侧的并发窗口：Broker 向消费者推送消息后，这些消息在 `ack`、`nack` 或 `reject` 前都计入未确认数量；窗口满时，RabbitMQ 会等消费者释放名额后再继续投递。",
      "RabbitMQ 的默认语义是按 consumer 生效。一个 channel 上启动多个 consumer，并在消费前设置 `basic.qos(10)`，每个 consumer 都可以各自持有最多 10 条未确认消息，这比跨队列共享一个 channel 窗口更符合常见工作队列模型。",
      "`global=true` 会增加 channel 级限制。RabbitMQ 可以同时执行 consumer 级限制和 channel 级限制，例如每个 consumer 最多 10 条、整个 channel 最多 15 条；这种配置需要队列与 channel 额外协调，在跨队列或集群场景下吞吐会下降。",
      "`prefetch=0` 表示无上限窗口。它适合极少数处理速度稳定、消息体很小、消费者内存充足的链路；在普通业务消费中，过大的窗口会让单个消费者囤积大量消息，放大内存、重复投递和故障恢复成本。",
      "预取数量与手动确认强相关。手动确认模式下，未确认窗口直接约束正在处理的消息数量；自动确认模式下，消息一投递就被视为完成，预取窗口对消费者过载的保护效果会明显减弱。",
      "调参时先看任务耗时和资源瓶颈：CPU 密集、耗时长、下游慢的任务通常从 1 到 10 这类小窗口开始；I/O 等待多、处理稳定、吞吐目标高的消费者可以逐步增大窗口，并观察 deliver rate、ack rate、consumer capacity、ready、unacked 和处理延迟。",
      "高预取会影响分发公平性。某个消费者先拿到大量消息后，其他消费者即使空闲也需要等待窗口释放；低预取能让任务更频繁地回到队列调度层，通常更利于慢消费者保护和公平分发。",
      "优先级队列尤其依赖合理预取。消费者窗口被低优先级消息占满时，新到达的高优先级消息会留在队列中等待，直到已有未确认消息被确认；因此优先级队列常搭配手动确认和较小的 `basic.qos` 使用。",
      "故障恢复也受预取影响。消费者宕机或连接关闭时，窗口里的未确认消息会回到可投递路径；窗口越大，一次故障带来的重复处理、重排队和下游补偿压力越大。",
      "排查时把 `messages_unacknowledged`、`messages_ready`、consumer capacity 和应用处理耗时放在一起看：`unacked` 高且处理延迟高，优先降低窗口或扩容消费者；`ready` 高且 `unacked` 低，重点检查消费者数量、订阅状态、连接/channel 和分发限制。",
      "参考来源：RabbitMQ Consumer Prefetch 文档说明了 `basic.qos`、按 consumer 生效、`prefetch=0` 和 `global` 组合语义；Consumer Acknowledgements 文档解释了手动确认、自动确认和 channel prefetch；Consumers 与 Monitoring 文档给出 consumer capacity、ready/unacked 等排查指标；Priority Queue 文档说明了预取窗口对优先级投递的影响。",
    ],
