    id: "persistent-message",
    zh: "消息持久化",
    en: "Persistent Message",
    area: "persistence",
    difficulty: "medium",
    concept: "消息持久化通过 `delivery_mode=2` 让消息进入持久化存储路径，配合 durable 队列和发布确认提升 Broker 重启后的消息保留能力。",
    explanation: [
      "消息持久化是发布端给消息设置的存储语义。在 AMQP 0-9-1 中，`delivery_mode=2` 表示 persistent，RabbitMQ 会把这类消息纳入持久化路径；`delivery_mode=1` 表示 transient，适合短暂通知、实时状态和可重建事件。",
      "可靠保留链路由 durable exchange、durable queue、persistent message 和 publisher confirm 共同构成。交换机和队列负责拓扑在重启后恢复，persistent message 负责消息进入持久化存储路径，publisher confirm 负责让发布者知道 Broker 已经接受这次发布并满足对应安全条件。",
      "持久化消息路由到 durable queue 后，RabbitMQ 会在发布确认前完成对应的持久化条件；经典队列通常涉及磁盘写入，quorum queue 还涉及多数副本确认。发布者收到 confirm 后，再把本地发送记录标记为成功。",
      "持久化也有时间窗口。消息从客户端写入 socket、Broker 接收、路由入队、写入磁盘或复制到副本之间存在多个阶段；应用以 publisher confirm 作为发布成功边界，可以覆盖 Broker 在写入完成前故障的情况。",
      "持久化消息仍会尽量使用内存工作集。现代 RabbitMQ 的经典队列和 quorum queue 会把数据主动写入磁盘，同时保留少量热数据在内存中提升消费效率；磁盘路径参与存储安全，内存路径参与吞吐和延迟。",
      "持久化会增加成本。磁盘写入、批量刷盘、队列索引、消息存储和副本复制都会影响发布确认延迟；高吞吐场景通常采用异步 confirm、批量发布、合理消息体大小和磁盘容量监控来提升效率。",
      "消息体越大，持久化链路的磁盘、网络和复制成本越明显。大文件、图片和报表通常放对象存储，RabbitMQ 消息只保存对象地址、业务 ID、校验信息和状态字段。",
      "持久化队列的 TTL、长度限制、死信策略依然会生效。消息被过期、达到队列长度上限、被消费者确认或被策略转移后，会按对应规则离开当前队列；持久化语义关注重启恢复，生命周期规则关注保留时间和容量边界。",
      "排查持久化问题时先看 publisher confirm 延迟、磁盘 I/O、free disk alarm、队列类型、消息大小、队列深度、unacked 数量和发布端重试日志。confirm 延迟突然升高，通常和磁盘压力、副本同步、消息体过大或队列堆积有关。",
      "参考来源：RabbitMQ Persistence Configuration 文档说明消息存储、队列索引和持久化层；Queues 文档说明 durable queue 与 message persistence 的关系；Confirms 文档说明 persistent 消息发布确认与磁盘写入时机；Publishers 与 Reliability 文档补充发布端数据安全；Classic Queues 文档补充经典队列持久化存储细节。",
    ],
