    id: "delivery-mode",
    zh: "投递模式",
    en: "Delivery Mode",
    area: "persistence",
    difficulty: "medium",
    concept: "投递模式是消息属性中的 `delivery_mode`，用 `1` 表示 transient、`2` 表示 persistent，决定消息进入队列后的持久化语义。",
    explanation: [
      "投递模式是发布消息时设置的消息属性。`delivery_mode=1` 表示 transient，适合实时通知、可重建状态和低价值事件；`delivery_mode=2` 表示 persistent，适合订单、支付、审计和需要 Broker 重启后保留的业务事件。",
      "它控制消息本身的存储语义；exchange 和 queue 的 `durable` 控制拓扑元数据的重启恢复。可靠保留通常同时需要 durable exchange、durable queue、persistent message 和 publisher confirm。",
      "组合关系要按链路看：persistent message 路由到 durable queue，才具备重启后保留的基础；persistent message 进入临时队列时，队列生命周期仍然决定消息去留；transient message 进入 durable queue 时，队列会恢复，消息按 transient 语义处理。",
      "RabbitMQ 的持久化层可能把 transient 消息写到磁盘，用于内存压力下的分页和运行期资源管理；这属于内部存储优化，应用仍应按 transient 语义设计恢复逻辑。",
      "publisher confirm 会受到投递模式影响。persistent message 路由到 durable queue 后，RabbitMQ 会在满足持久化条件后发送 `basic.ack`；quorum queue 还需要多数副本接受并确认。transient message 的确认路径通常更短，发布延迟更低。",
      "确认顺序也会受投递模式和目标队列影响。发布确认是异步到达的，同一 channel 上大多数情况下保持发布顺序，但不同消息进入的队列类型、持久化路径和批量刷盘时机可能让确认到达时间不同。",
      "性能取舍很直接：persistent 增加磁盘写入、队列索引、消息存储和复制成本，换来更强的重启恢复能力；transient 减少持久化成本，适合丢失后可重算或可忽略的消息。",
      "设置层面要用客户端库的消息属性完成，例如 Java 客户端常见写法是 `MessageProperties.PERSISTENT_TEXT_PLAIN` 或 `BasicProperties.Builder().deliveryMode(2)`；统一封装发布方法可以避免不同业务线漏设关键属性。",
      "排查时重点看消息属性、队列 durable 配置、exchange durable 配置、publisher confirm 模式、mandatory return、磁盘告警、队列类型和发布端重试记录。属性设置正确后，再看路由结果和确认结果是否符合预期。",
      "参考来源：AMQP 0-9-1 Model 文档说明消息属性、exchange/queue durable 与消息持久化的关系；Persistence Configuration 文档说明 persistent 与 transient 消息在存储层的处理；Confirms 文档说明投递模式对发布确认时机的影响；Publishers 与 Reliability 文档补充发布端可靠性边界。",
    ],
