    concept: "磁盘水位通过 `disk_free_limit` 保护 Broker 可用磁盘空间，低于阈值时触发磁盘告警并阻塞发布连接。",
    explanation: [
      "磁盘水位是 RabbitMQ 的资源保护机制。节点定期检查可用磁盘空间，当可用空间低于 `disk_free_limit` 时触发 disk alarm，Broker 会阻塞生产者发布，防止持久化消息、队列索引和日志继续消耗剩余空间。",
      "`disk_free_limit` 可以配置为固定字节数，也可以配置为相对内存的比例。生产环境通常按磁盘容量、消息峰值、恢复时间和运维预留空间设置阈值，并把它纳入容量规划。",
      "disk alarm 触发后，发布连接会被阻塞，发布端表现为 confirm 变慢、写入卡住或连接进入 blocked 状态；消费者仍可继续消费，目标是通过消费释放磁盘、让系统回到安全水位。",
      "集群中某个节点触发磁盘告警，会影响整个集群的发布行为。因为消息可能路由到任意队列主副本或涉及跨节点复制，集群选择整体限速来保护最紧张的节点。",
      "磁盘水位和持久化链路强相关。persistent message、durable queue、quorum queue、经典队列存储、消息分页和大消息都会增加磁盘压力；发布确认延迟升高时，要同时看磁盘 I/O、队列堆积和 free disk 指标。",
      "惰性队列和现代经典队列都会更多依赖磁盘路径。它们能降低内存压力，但会提高对磁盘容量和吞吐的要求；队列长期堆积时，磁盘水位会成为发布端背压的主要触发点。",
      "恢复动作按安全优先级执行：暂停或降低发布流量、扩容磁盘、清理无效队列和旧日志、加快消费者处理、设置 TTL 或长度限制、迁移堆积队列。业务消息清理需要先确认补偿和审计要求。",
      "排查时看节点级 `disk_free`、`disk_free_limit`、alarm 状态、connection blocked、publish rate、confirm latency、队列 ready/unacked、消息体大小和磁盘 IOPS。磁盘水位恢复后，blocked 连接会解除，发布确认延迟通常会逐步下降。",
      "常见特殊情况包括容器磁盘配额、挂载点选择错误、日志占满磁盘、镜像或 quorum 副本放大写入、消费者停滞导致队列堆积、临时大消息洪峰。它们都会让磁盘水位和业务流量看起来同时异常。",
      "参考来源：RabbitMQ Free Disk Space Alarms 文档说明 `disk_free_limit`、告警触发和发布阻塞行为；Monitoring 文档给出资源水位与连接状态指标；Persistence Configuration、Queues 和 Lazy Queues 文档说明消息存储与队列堆积对磁盘的影响；Publishers 文档补充发布端 blocked/confirm 体验。",
    ],
