    concept: "消息 TTL 用毫秒级过期时间限制消息在队列中的存活期，过期消息会被丢弃或按死信配置转发。",
    explanation: [
      "TTL 是 Time-To-Live，表示消息在队列中允许停留的时间。RabbitMQ 支持按队列设置消息 TTL，也支持发布时给单条消息设置 expiration；两种 TTL 同时存在时，较小的过期时间生效。",
      "按队列设置 TTL 常用策略 policy 或队列参数 `x-message-ttl`，适合统一控制某类队列中的消息生命周期，例如订单超时、通知过期和临时任务清理。官方更推荐用 policy 管理可变配置，方便在线调整。",
      "按消息设置 TTL 使用消息属性 `expiration`，它通常是字符串形式的毫秒值，适合不同消息有不同截止时间的场景。客户端要统一封装这个属性，避免不同业务传秒、毫秒或空值导致行为不一致。",
      "`0` 是特殊值，表示消息一进入队列就过期；如果队列存在可用消费者，消息仍可能被立即投递。它常用于只接受即时消费的任务模型，需要结合真实消费者状态验证。",
      "消息过期后会从当前队列移除；队列配置了 dead-letter exchange 时，过期消息会按死信规则重新发布到死信交换机。延迟队列方案常利用 TTL 加死信交换机，让消息先在延迟队列等待，再转入业务队列。",
      "过期清理有队列位置影响。对于按消息 TTL 的经典队列，过期消息可能等到到达队头或被队列扫描时才真正移除；因此队列指标中可能短时间看到已经逻辑过期的消息仍占用队列深度。",
      "给已有队列追溯应用 TTL 时，旧消息会按照新规则判断过期，但清理和死信转发需要队列处理过程推进。大批量旧消息同时过期可能造成死信交换机、目标队列和消费者瞬时压力。",
      "TTL 与持久化、确认和消费状态各管一段生命周期。TTL 作用于队列中的 ready 消息；已经投递给消费者并处于 unacked 的消息由确认机制管理，消费者长时间处理不会因为原队列 TTL 自动释放。",
      "排查时看队列 policy、`x-message-ttl`、消息 `expiration`、dead-letter exchange/routing-key、ready/unacked、publish rate、dead-letter rate 和消费者处理时间。延迟任务异常时，还要检查延迟队列绑定和死信路由是否匹配。",
      "参考来源：RabbitMQ Time-To-Live 文档说明 per-queue TTL、per-message TTL、`0`、过期清理和追溯应用行为；Dead Letter Exchanges 文档说明过期消息的死信转发；Queues 与 Monitoring 文档帮助理解队列状态和排查指标。",
    ],
