    id: "dead-letter-exchange",
    zh: "死信交换机",
    en: "Dead Letter Exchange",
    area: "dead-letter",
    difficulty: "medium",
    concept: "死信交换机是接收死信消息的普通交换机，用来承接拒绝、过期、超过长度限制或 quorum delivery-limit 的消息。",
    explanation: [
      "DLX 本质上是一个普通 exchange，可以是 direct、topic、fanout 或 headers。队列配置 dead-letter exchange 后，满足死信条件的消息会从原队列重新发布到这个 exchange，再按绑定关系进入死信队列或补偿队列。",
      "RabbitMQ 的死信触发原因有四类：消费者 `basic.reject` 或 `basic.nack` 且 `requeue=false`，消息 TTL 过期，队列超过长度限制，quorum queue 的 delivery-limit 被触发。整个队列自身过期时，队列里的消息会随队列删除。",
      "DLX 配置通常使用 policy，例如 `dead-letter-exchange` 和 `dead-letter-routing-key`。队列声明参数 `x-dead-letter-exchange` 和 `x-dead-letter-routing-key` 也能生效；policy 更适合线上调整，因为它可以统一管理一批队列。",
      "路由键决定死信去向。配置了 `dead-letter-routing-key` 时，死信消息使用该路由键重新发布；未配置时，RabbitMQ 使用消息原始路由键。生产环境要给 DLX 绑定明确的死信队列，避免消息进入无绑定路径。",
      "权限也会影响 DLX 生效。声明源队列的用户需要对源队列具备 read 权限，并对目标 dead letter exchange 具备 write 权限；权限在队列声明时校验。",
      "目标 DLX 需要在死信发生前存在。源队列声明时可以先引用目标 exchange 名称；真正死信转发时如果目标 exchange 缺失，消息会被丢弃并留下排查难度很高的空洞。",
      "死信转发会修改消息头。RabbitMQ 会记录 `x-death`，包含来源队列、原因、次数、时间等信息；多次死信会压缩相同 `{Queue, Reason}` 组合。这个头常用于判断重试次数、失败原因和是否进入补偿流程。",
      "DLX 存在循环风险。消息从队列 A 死信到交换机后又路由回队列 A，就形成死信循环；RabbitMQ 会检测循环，并在整轮循环没有消费者拒绝动作时丢弃消息。工程上应通过路由键、隔离交换机和重试次数上限打断循环。",
      "安全性要按队列类型理解。默认死信重新发布在 Broker 内部执行，内部发布确认关闭，目标队列不可用时可能丢失；quorum queue 支持 at-least-once dead-lettering，可以在内部转发时使用发布确认提升安全性。",
      "排查 DLX 时看死信触发原因、源队列 policy、`x-dead-letter-*` 参数、目标 exchange/queue 绑定、权限、`x-death`、dead-letter rate、目标队列 ready/unacked 和消费者日志。延迟重试场景还要检查 TTL 与死信路由是否组成闭环。",
      "参考来源：RabbitMQ Dead Letter Exchanges 文档说明死信触发原因、policy/参数配置、路由键、权限、循环、安全性和 `x-death`；TTL 文档说明过期进入 DLX；Negative Acknowledgements 与 Confirms 文档补充拒绝、确认和内部转发安全边界；Queues 与 Monitoring 文档辅助排查队列状态。",
    ],
