    id: "dead-letter-queue",
    zh: "死信队列",
    en: "Dead Letter Queue",
    area: "dead-letter",
    difficulty: "medium",
    concept: "死信队列是绑定到死信交换机的普通队列，用于承接异常消息、延迟重试消息和需要人工补偿的消息。",
    explanation: [
      "死信队列本质上是普通 queue。它通过 binding 绑定到 dead-letter exchange，接收从业务队列转发出来的死信消息；它的队列类型、durable、TTL、长度限制、消费者和权限都按普通队列规则管理。",
      "标准链路是业务队列配置 DLX，DLX 绑定死信队列。业务消息因为 `requeue=false`、TTL 过期、队列长度超限或 quorum delivery-limit 进入 DLX，再按死信路由键落到对应死信队列。",
      "死信队列适合三类处理：问题消息留存供排查，失败消息进入延迟重试链路，确认无法自动恢复的消息进入人工补偿。生产环境通常按业务域拆分死信队列，避免不同业务的失败消息混在一起。",
      "`x-death` 是死信队列排查的核心线索。它记录来源队列、原因、次数和时间；`reason` 可能是 `rejected`、`expired`、`maxlen` 或 `delivery_limit`。业务可以用它判断失败来源、重试次数和告警级别。",
      "消息第一次进入死信链路时，RabbitMQ 还会写入 `x-first-death-*`，后续死信会更新 `x-last-death-*`。这些字段能帮助定位最早出问题的队列和最近一次转发路径。",
      "TTL 死信会移除原消息的 TTL，避免消息到达死信队列后继续因为原 TTL 过期；原始过期属性会保存在 `original-expiration`。因此死信队列的保留时间要单独配置，例如使用队列 TTL 或消费者归档策略。",
      "死信队列用于重试时，要控制次数和节奏。常见做法是消费者读取 `x-death` 计数，小于上限则投递到延迟队列，达到上限后保留在最终死信队列，并触发告警或人工处理。",
      "死信队列容量需要单独治理。目标队列消费者停滞、重试风暴、下游长时间故障和大批量 TTL 过期都会造成死信队列积压；应配置告警、容量上限、保留策略和补偿任务，避免它成为新的堆积点。",
      "安全性取决于源队列和目标队列能力。默认死信内部转发使用关闭的发布确认，目标队列不可用时存在丢失风险；quorum queue 支持 at-least-once dead-lettering，适合高价值异常消息链路。",
      "排查时同时看源队列死信配置、DLX 绑定、死信队列 ready/unacked、`x-death`、消费者日志、dead-letter rate、告警和业务补偿记录。死信队列持续增长时，优先定位失败原因占比和消费端处理能力。",
      "参考来源：RabbitMQ Dead Letter Exchanges 文档说明死信触发、路由、循环、`x-death` 与安全性；TTL 文档说明过期死信与过期属性处理；Negative Acknowledgements 与 Confirms 文档补充拒绝和确认边界；Queues 与 Monitoring 文档用于理解队列配置和指标。",
    ],
