    id: "delay-queue",
    zh: "延迟队列",
    en: "Delay Queue",
    area: "delay-retry",
    difficulty: "medium",
    concept: "延迟队列让消息先等待一段时间，再进入业务队列消费，常用 TTL + DLX 或 delayed message exchange 插件实现。",
    explanation: [
      "RabbitMQ 没有内置独立的 delay queue 类型，工程上常用两种方案：TTL + Dead Letter Exchange，或 delayed message exchange 插件。前者基于官方队列能力，后者用 `x-delayed-message` exchange 和 `x-delay` 头表达每条消息的延迟时间。",
      "TTL + DLX 的链路是：消息进入延迟队列，等待 TTL 到期，过期后被重新发布到 dead-letter exchange，再路由到业务队列。它适合固定延迟、分级延迟和重试退避，例如 1 分钟、5 分钟、30 分钟多个延迟队列。",
      "按队列 TTL 配置 `x-message-ttl` 或 policy，适合整条延迟队列使用同一等待时间；按消息 TTL 配置 `expiration`，适合同一队列中消息延迟不同的场景，但经典队列会受队头清理影响，长延迟消息可能挡住后续短延迟消息释放。",
      "delayed message exchange 插件把延迟放在 exchange 层处理。发布者发送到 `x-delayed-message`，通过 `x-delay` 头指定毫秒级延迟，时间到达后再按底层 exchange 类型路由到队列；它更适合按消息动态延迟。",
      "插件方案需要评估部署和版本。它依赖 RabbitMQ 插件安装、启用和运维升级，集群所有相关节点都要具备能力；高可靠场景要结合官方插件文档、集群变更流程和压测结果做准入。",
      "延迟队列常用于失败重试。消费者处理失败后按异常类型计算下一次重试时间，把消息投递到对应延迟队列；到期后回到业务队列再消费。配合 `x-death`、业务重试字段或 quorum delivery count 控制次数上限。",
      "顺序是重要边界。延迟队列会改变原队列的到达顺序，重试消息回流后也会和新消息交错；同一业务键要求顺序时，应使用分区路由、单活消费者或独立重试通道。",
      "容量风险集中在延迟积压和集中释放。大量消息同一时间过期会冲击 DLX、业务队列和消费者；重试风暴会让失败消息反复占用资源。应设置重试上限、退避间隔、告警和下游保护。",
      "可靠性要看整条链路：发布到延迟队列要用 publisher confirm，延迟队列、DLX、业务队列要使用 durable 配置，高价值失败消息还要关注死信内部转发安全性和目标队列可用性。",
      "排查时看延迟队列 ready、业务队列 ready/unacked、dead-letter rate、publish/confirm latency、`x-death`、消息 `expiration` 或 `x-delay`、DLX 绑定和消费者错误率。延迟不准时通常和队头阻塞、队列堆积、插件状态或消费者能力有关。",
      "参考来源：RabbitMQ TTL 文档说明 per-queue/per-message TTL 与过期清理；Dead Letter Exchanges 文档说明过期后重新发布和死信路由；Delayed Message Exchange 插件文档说明 `x-delayed-message` 与 `x-delay`；Negative Acknowledgements、Confirms 和 Monitoring 文档补充失败重试、发布可靠性和指标排查。",
    ],
