      "声明交换机时需要设置 `x-delayed-type`，例如 `direct`、`topic` 或 `fanout`。`x-delayed-message` 像代理层一样先保存延迟消息，到期后再按 `x-delayed-type` 指定的交换机语义执行路由。",
      "`x-delay` 支持每条消息单独设置延迟时间。插件示例中 5000ms 和 1000ms 的两条消息会按到期时间先后投递；未设置 `x-delay` 的消息会直接路由。",
      "插件适合秒、分钟、小时级延迟，最多一两天这类短期调度。长期预约任务、海量延迟积压和跨月份计划任务更适合外部调度系统、数据库任务表或商业版 delayed queue 能力。",
      "当前插件仓库已经归档，RabbitMQ 团队在 2026-04-16 将仓库设为只读，并说明该项目已停止维护。新项目选型应把维护状态、RabbitMQ 版本、Khepri/Mnesia 依赖和升级路径纳入评审。",
      "可靠性边界要认真评估。插件把延迟消息存到当前节点的 Mnesia 表并使用单个磁盘副本；节点丢失、插件停用或插件禁用时，尚未投递的延迟消息存在丢失风险。",
      "路由安全也有边界。插件到期后只尝试发布一次，mandatory 标志无法覆盖未来时刻的路由失败；到期时缺少匹配队列或 binding，消息可能进入不可达路径。关键业务要有审计、补偿和定期扫描。",
      "性能方面，`x-delayed-message` 需要判断延迟范围、保存延迟消息并维护定时逻辑；把它当作普通 exchange 长期承载所有消息会增加开销。普通即时消息应走直接的 direct/topic/fanout 交换机。",
      "与 TTL + DLX 相比，插件更方便表达每条消息动态延迟；TTL + DLX 的优点是可见性更强、可清理、可用复制队列类型保存延迟消息。工程选型要看运维成本、延迟精度、可靠性和积压规模。",
      "排查时看插件启用状态、exchange 类型和 `x-delayed-type`、消息 headers 中的 `x-delay`、目标 binding、publish confirm、节点重启记录、插件禁用记录和目标队列 ready/unacked。延迟消息规模大时还要监控内存、磁盘和确认延迟。",
      "参考来源：Delayed Message Exchange 插件 README 说明 `x-delayed-message`、`x-delay`、`x-delayed-type`、适用范围、性能影响、Mnesia 存储、mandatory 边界和归档状态；Exchanges、Publishers、Confirms、TTL 与 DLX 文档用于对比普通交换机、发布可靠性和 TTL+DLX 方案。",
