    id: "idempotency",
    zh: "消费幂等",
    en: "Consumer Idempotency",
    area: "engineering",
    difficulty: "medium",
    concept: "消费幂等让同一消息被重复投递、重复消费或重试时，业务结果保持稳定且副作用只生效一次。",
    explanation: [
      "RabbitMQ 提供的是至少一次处理语义。连接断开、消费者崩溃、ack 丢失、重试、requeue、DLX 回流都会让同一消息再次出现；消费幂等把重复投递视为正常分支来设计。",
      "幂等的核心是给业务动作一个稳定身份。常用身份包括 messageId、订单号、支付流水号、库存操作号、业务事件 ID；消费者用这个身份判断同一动作是否已经完成。",
      "最稳的做法是去重记录和业务写入在同一事务里完成。例如先向 `processed_message(subscriber_id, message_id)` 插入记录，再更新订单状态；唯一键冲突代表消息已经处理，可以直接 ack。",
      "另一种做法是在业务实体上记录已处理事件。比如订单表保存 lastEventId、version 或状态流转记录，消费者用条件更新保证同一事件只能推进一次。",
      "ack 时机很关键。消费者应在业务事务提交成功后 ack；如果先 ack 再写数据库，业务失败会造成消息丢失；如果写成功后 ack 失败，消息会重复投递，幂等逻辑会吸收重复。",
      "副作用操作要拆出幂等键。调用支付、发券、发短信、扣库存这类外部动作时，要向下游传业务唯一键，或先写本地任务表再由幂等任务执行，避免重试导致重复扣款、重复通知或重复出库。",
      "幂等和消息去重有区别。去重关注识别重复消息，幂等关注重复执行后的业务结果；可靠系统通常两者一起使用：去重减少重复执行，幂等兜住并发、重试和补偿中的残余重复。",
      "顺序和并发也要纳入设计。同一业务键的多条消息可能乱序或并发到达，消费者要用版本号、状态机、条件更新或分区消费保证状态只按允许路径变化。",
      "死信和重试链路要保留幂等上下文。进入 DLQ 或补偿队列的消息仍要携带 messageId、业务键、retryCount、`x-death` 和错误原因，方便补偿任务按同一规则处理。",
      "排查时看重复 messageId 次数、唯一键冲突率、业务条件更新失败数、ack 失败、redelivery rate、最终 DLQ、补偿任务执行结果和下游幂等键命中率。重复率升高时，先确认连接稳定性、消费者异常和确认时机。",
      "参考来源：Microservices.io Idempotent Consumer Pattern 说明 processed message 表和业务实体记录两种方案；RabbitMQ Reliability 与 Confirms 文档说明重复投递和确认边界；Negative Acknowledgements、DLX 与 Monitoring 文档补充重试、死信和排查指标。",
    ],
