      "Redis 去重适合短周期、高吞吐场景。常见命令是 `SET dedup:{messageId} 1 NX EX <ttl>`，`NX` 保证首次写入成功，`EX` 控制窗口长度；TTL 要覆盖消息重试、延迟投递和人工补偿窗口。",
      "Redis 方案要评估故障恢复、键淘汰和 TTL 到期后的重复窗口。支付、扣款、出库这类关键写入应继续保留数据库唯一约束或业务状态幂等，让 Redis 承担前置过滤和削峰职责。",
      "布隆过滤器可以在海量消息中做预过滤，价值在于节省后端存储查询；它存在误判概率，关键业务仍要落到精确存储确认。",
      "去重和幂等的分工要清楚。去重负责识别重复并拦截多数重复执行，幂等负责保证重复执行后的业务结果稳定；可靠消费者通常先做去重，再用业务幂等兜住并发和边界情况。",
      "并发场景要依赖原子操作。多个消费者可能同时拿到同一消息，去重逻辑要用数据库唯一键、条件更新或 Redis `SET NX` 完成占位，普通的先查后插会出现竞争窗口。",
      "ack 应放在去重记录和业务事务提交之后。业务已提交而 ack 失败时，消息再次投递会命中去重记录；消费者确认后再写业务会扩大丢失窗口。",
