      "参考来源：Microservices.io Idempotent Consumer Pattern 给出去重表和业务实体记录两种经典方案；RabbitMQ Reliability、Confirms 与 Negative Acknowledgements 解释重复投递和确认边界；Redis SET 文档说明 `NX`、`EX` 的原子语义；RabbitMQ Monitoring 文档用于定位重复投递相关指标。",
