    id: "redis-dedup",
    zh: "Redis 去重",
    en: "Redis Deduplication",
    area: "engineering",
    difficulty: "medium",
    concept: "Redis 去重用原子写入和过期时间记录消息处理窗口，快速拦截短周期重复投递。",
    explanation: [
      "Redis 去重的核心是把消息的稳定身份写成一个短生命周期 key，例如 `dedup:{messageId}` 或 `dedup:{orderId}:{eventType}`。消费者先抢占这个 key，再决定是否执行业务。",
      "常用命令是 `SET dedup:{id} 1 NX EX <ttl>`。`NX` 表示 key 首次出现时写入成功，`EX` 表示同时设置秒级过期时间；这条命令把判断存在、写入、设置过期合成一次原子操作。",
      "TTL 是 Redis 去重的关键参数。它要覆盖 RabbitMQ 的重试间隔、延迟队列时间、消费者重启恢复时间和人工补偿窗口；TTL 过短会让旧消息再次穿透，TTL 过长会增加内存压力并扩大误拦截窗口。",
      "生产上常用两段式状态。消费者先写 `processing` 短 TTL 防并发，业务成功后改成 `done` 长 TTL 并 ack；业务失败时删除 `processing` 或等待它过期，让后续重试继续处理。",
      "只写一个 `done` key 的方案适合处理耗时短、失败重试简单的场景。对于支付、出库、发券这类关键副作用，Redis 负责前置拦截，数据库唯一键、状态机或下游幂等键负责最终一致。",
      "key 设计要选择业务唯一键优先。messageId 适合生产者能稳定复用 ID 的链路；订单号、支付流水号、事件 ID 更适合跨服务重试、人工补偿和 DLQ 回放。",
      "Redis key 要有命名空间和版本，例如 `mq:dedup:v1:{consumer}:{businessKey}`。把消费者名纳入 key 可以支持同一消息被多个订阅者各自处理，把版本纳入 key 可以支持规则变更后的平滑切换。",
      "Redis 去重对并发很友好。多个消费者同时处理同一消息时，只有一个消费者能通过 `SET NX` 抢到 key；其他消费者命中已有 key 后应根据状态选择 ack、延迟重试或记录冲突。",
      "Redis 故障、主从切换、内存淘汰、TTL 到期都会影响去重窗口。关键业务要把 Redis 去重视为性能层，并保留可持久化的幂等记录和业务状态检查。",
      "ack 时机要跟处理状态配套。只有业务提交成功且 `done` 状态写入成功后才 ack；如果只拿到 `processing` 就 ack，消费者崩溃会让业务处理缺口变大。",
      "排查时看 Redis `SET NX` 成功率、重复命中率、key 数量、内存占用、过期速率、evicted_keys、TTL 分布、RabbitMQ redelivery rate、ack 失败和 DLQ 回放结果。",
      "参考来源：Redis SET、EXPIRE、TTL 官方文档说明 `NX`、过期时间和 TTL 查询语义；RabbitMQ Reliability 与 Monitoring 文档说明重复投递来源和观测指标；Microservices.io Idempotent Consumer Pattern 补充持久化幂等记录的落地方式。",
    ],
