    id: "transactional-outbox",
    zh: "事务外盒",
    en: "Transactional Outbox",
    area: "engineering",
    difficulty: "hard",
    concept: "事务外盒把业务变更和待发布消息写入同一数据库事务，再由独立发布器把外盒记录可靠投递到 RabbitMQ。",
    explanation: [
      "事务外盒解决的是业务数据库写入和消息发布之间的一致性窗口。下单、扣库存、创建支付单这类操作先把业务数据和待发送事件写进同一个本地事务，事务提交后再由后台发布器异步投递。",
      "核心表通常叫 outbox，字段包括 id、aggregateType、aggregateId、eventType、payload、routingKey、status、retryCount、nextRetryAt、createdAt、publishedAt 和 error。payload 保存事件内容，routingKey 决定 RabbitMQ 路由。",
      "写入流程要保持简单：业务服务在同一数据库事务里更新业务表并插入 outbox 记录。这样数据库提交成功就一定能看到待发布事件，数据库回滚时事件记录也一起回滚。",
      "发布流程由 relay、scheduler 或 CDC 组件承担。它按状态扫描 pending 记录，发布到 RabbitMQ，等待 publisher confirm 成功后把记录标记为 published；失败则记录错误、增加 retryCount，并按退避时间等待下一轮。",
      "RabbitMQ 侧要配合发布确认。publisher confirm 用于判断 Broker 是否接收发布请求，mandatory 或 return 机制可以暴露无法路由的消息，监控要覆盖未确认发布、发布失败和 unroutable 事件。",
      "事务外盒的交付结果通常是至少一次发布。发布器可能在消息已进入 RabbitMQ 后崩溃，数据库状态仍停留在 pending，重启后会再次发布；因此消息必须携带稳定 eventId，消费者要做幂等和去重。",
      "外盒表需要并发领取机制。多实例发布器可以用 `FOR UPDATE SKIP LOCKED`、乐观锁版本号或状态 CAS 领取记录，确保同一批记录由一个实例发布，避免高并发下重复扫描放大。",
      "顺序要求要按业务聚合设计。同一订单、账户或库存项的事件可以按 aggregateId 分区、单线程发布或使用递增版本号，消费者用版本和状态机处理乱序到达。",
      "外盒表会持续增长，必须设计归档和清理。published 记录可按时间分区、冷归档或定期删除；pending 和 failed 记录要保留足够长的排障窗口并接入告警。",
      "失败治理要分层：临时网络失败走退避重试，路由配置错误进入 failed 并报警，payload 序列化错误进入人工修复队列。重试次数、下一次重试时间和最后错误原因要写回外盒表。",
      "排查时看 pending 数量、最老 pending 年龄、publish confirm 延迟、retryCount 分布、failed 数量、unroutable 数量、RabbitMQ 入队速率、消费者去重命中率和端到端事件延迟。",
      "参考来源：Microservices.io Transactional Outbox Pattern 说明本地事务加消息中继的模式；RabbitMQ Confirms、Reliability 与 Publisher Confirms Tutorial 解释发布确认和可靠发布边界；Idempotent Consumer Pattern 说明消费者侧幂等需求；RabbitMQ Monitoring 文档补充观测指标。",
    ],
