    id: "order-consumption",
    zh: "顺序消费",
    en: "Ordered Consumption",
    area: "engineering",
    difficulty: "hard",
    concept: "顺序消费按业务键约束消息进入同一有序通道，并用消费者并发、确认、重试和版本控制维持业务状态推进顺序。",
    explanation: [
      "顺序消费先定义排序范围。通常需要保证的是同一订单、同一账户、同一库存项内的事件顺序，而全局顺序成本很高，会把整个系统压成单队列单消费者。",
      "RabbitMQ 队列本身按入队顺序投递，但多消费者、较大的 prefetch、nack requeue、连接恢复和重试回流都会改变业务处理完成顺序。因此顺序消费要关注处理顺序，而非只看投递顺序。",
      "最严格的方案是一个队列配一个消费者，并把 prefetch 设置为 1。这个方案理解成本最低，吞吐也最低，适合账户流水、订单状态机这类强顺序小流量链路。",
      "更常见的方案是按业务键分区。生产者用 orderId、userId、accountId 等生成 routingKey 或哈希分片，让同一业务键固定进入同一队列；不同分片并行消费，同一分片内部串行处理。",
      "分区数量要按峰值吞吐和热点键设计。队列太少会造成堆积，队列太多会增加连接、channel、监控和扩缩容复杂度；热点订单或热点用户还需要单独拆分或业务限流。",
      "消费者并发要跟分区模型匹配。同一分区内可以使用单线程处理或 Single Active Consumer；跨分区可以并行扩容。prefetch 过大时，同一消费者会提前拿到多条消息，失败重试时更容易形成局部乱序。",
      "重试是顺序消费最容易出问题的环节。同一业务键的第 N 条消息失败后，第 N+1 条继续执行会破坏状态机；常用做法是阻塞该业务键、把失败消息进入延迟重试并暂停后续键内消息，或让消费者用版本号拒绝越级状态。",
      "业务状态要自带顺序校验。事件里携带 sequence、version 或状态迁移前置条件，消费者使用条件更新，例如 `where version = previousVersion`，这样乱序到达会被识别并进入等待、重试或人工处理。",
      "事务外盒可以帮助生产端按聚合生成递增事件。外盒表按 aggregateId 和 version 发布，消费者再按同一字段校验，能把顺序约束从消息系统延伸到业务数据。",
      "死信和人工回放要保持同一分区规则。DLQ 回放时仍使用原 businessKey、routingKey、messageId 和 sequence；回放到其他队列会绕过原有串行通道。",
      "顺序消费的监控重点包括单分区队列深度、最老消息年龄、消费者数量、prefetch、redelivery rate、版本冲突数、重试队列长度、热点 key 分布和端到端状态推进延迟。",
      "参考来源：RabbitMQ Queues、Consumers、Consumer Prefetch、Confirms 与 Reliability 文档说明队列、消费者、确认和重投递语义；Modulus Hash Exchange 文档提供按键分片思路；JavaGuide 与 doocs advanced-java 补充顺序消费的工程面试和实践场景。",
    ],
