    id: "peak-shaving",
    zh: "削峰填谷",
    en: "Peak Shaving",
    area: "engineering",
    difficulty: "medium",
    concept: "削峰填谷用队列暂存突发请求，让消费者按可控速率持续处理，保护数据库、外部接口和核心服务容量。",
    explanation: [
      "削峰填谷的核心是把瞬时高峰转成可消化的队列积压。生产者快速把任务写入 RabbitMQ，消费者按数据库、缓存、第三方接口和 CPU 的承载能力稳定出队。",
      "队列承担缓冲池角色。RabbitMQ 队列是有序消息集合，可以把秒杀下单、批量导入、通知发送、日志写入这类突发任务从同步链路拆出来，降低入口请求对下游的瞬时冲击。",
      "削峰能力要用容量公式估算：可承受高峰时长大致等于可用队列容量除以生产速率和消费速率的差值。消费速率由消费者实例数、单实例并发、单条处理耗时、prefetch 和下游限流共同决定。",
      "prefetch 控制每个消费者可持有的未确认消息数量。prefetch 太小会让吞吐爬升慢，prefetch 太大容易让慢消费者占住大量消息，并在失败恢复时带来更多重新投递。",
      "消费者扩缩容负责把填谷速度调上来。队列深度、最老消息年龄和消费耗时持续上升时，可以增加消费者实例或分区队列；下游压力升高时，要降低并发或限速，避免把堆积从 RabbitMQ 转移到数据库。",
      "队列类型会影响削峰边界。Classic Queue 适合常规工作队列，Quorum Queue 适合更高可靠性场景；大量积压时要关注磁盘、内存、复制开销和确认延迟。",
      "削峰填谷需要入口控制。队列长度、消息 TTL、业务过期时间、租户配额和拒绝策略要提前设定；当队列积压超过可接受延迟时，系统应返回排队、降级、限购或稍后重试。",
      "消息有效期要和业务 SLA 对齐。秒杀订单、验证码、实时通知都有时间价值，过期消息继续消费会浪费资源；可以用消息 TTL、死信队列和业务状态检查处理过期任务。",
      "可靠性要靠持久化和确认链路兜住。核心任务使用 durable queue、persistent message、publisher confirm 和手动 ack；消费者在业务提交成功后确认消息，失败进入重试或死信治理。",
      "削峰填谷的边界在总容量。Broker 磁盘报警、内存水位、流控、队列长度上限和下游长期不可用都会让缓冲池失去吸收能力；容量规划要包含最坏峰值、恢复时间和清空积压时间。",
      "排查时看入队速率、出队速率、ack 速率、队列深度、最老消息年龄、consumer capacity、unacked 数量、磁盘水位、内存水位、消费者错误率和下游响应时间。",
      "参考来源：RabbitMQ Queues 文档说明队列有序缓冲和队列属性；Consumers 与 Consumer Prefetch 文档说明消费者吞吐和未确认消息控制；Classic/Quorum Queue、Disk Alarms 与 Monitoring 文档补充队列类型、资源水位和监控指标；doocs advanced-java 补充削峰填谷的高并发业务场景。",
    ],
