    id: "back-pressure",
    zh: "背压",
    en: "Back Pressure",
    area: "operations",
    difficulty: "medium",
    concept: "背压把消费者、下游服务和 Broker 的压力向上游传递，通过限速、预取、流控和扩缩容让系统在容量范围内运行。",
    explanation: [
      "背压的本质是压力反馈。消费者处理变慢、数据库响应变慢、队列积压升高或 Broker 资源紧张时，系统把信号传回上游，让生产速率和消费能力重新匹配。",
      "消费者侧最直接的背压手段是 prefetch。它限制每个消费者未确认消息数量，避免慢消费者一次拿走太多任务；prefetch 过大容易堆积 unacked，prefetch 过小会降低吞吐。",
      "应用侧要配合业务限速。数据库连接池、第三方接口额度、线程池队列和 CPU 饱和时，消费者应降低并发、延迟拉取或暂停消费，让队列承担缓冲，而不是把压力继续压到下游。",
      "队列侧背压通过队列深度、最老消息年龄、consumer capacity 和消费滞后体现。队列深度持续上升说明生产速率高于处理速率，consumer capacity 低说明队列有更多消息可以派发但消费者消化速度有限。",
      "Broker 侧背压来自资源水位。磁盘空间告警、内存水位和内部流控会限制发布链路，发布者会感受到延迟上升、confirm 变慢或连接被阻塞。",
      "发布者也要识别背压信号。publisher confirm 延迟、channel blocked 通知、发布超时和返回错误都应触发退避、降速、排队或入口限流，继续高速发布会扩大积压和恢复时间。",
      "背压和削峰填谷是一组配套机制。削峰填谷用队列吸收短峰，背压负责在积压接近容量边界时把压力传回入口，防止队列、Broker 和下游服务一起失控。",
      "背压策略要分层设计：消费者限速保护下游，prefetch 控制 in-flight，队列长度和 TTL 控制延迟边界，Broker 水位保护节点，入口限流保护整体服务质量。",
      "常见处理动作包括调低消费者并发、调小 prefetch、增加消费者实例、拆分热点队列、开启业务降级、暂停低优先级生产者、延长重试间隔和提升下游容量。",
      "背压指标要有告警阈值和恢复条件。只看队列深度会漏掉消费耗时和资源水位；只看 CPU 会漏掉下游慢查询、confirm 延迟和 unacked 堆积。",
      "排查顺序可以从下游开始：先看数据库或外部接口耗时，再看消费者处理耗时与错误率，然后看 unacked、队列深度、consumer capacity、磁盘水位、内存水位和发布确认延迟。",
      "参考来源：RabbitMQ Consumer Prefetch 文档说明未确认消息数量控制；Consumers 文档说明 consumer capacity 指标；Publishers、Queues、Disk Alarms、Monitoring 与 Reliability 文档补充发布端信号、队列积压、资源水位和可靠性边界；doocs advanced-java 补充高并发削峰和背压场景。",
    ],
