    id: "flow-control",
    zh: "流控",
    en: "Flow Control",
    area: "operations",
    difficulty: "medium",
    concept: "流控是 RabbitMQ 在内存、磁盘或内部进程压力升高时对发布链路施加的限速保护，用来维持节点稳定。",
    explanation: [
      "RabbitMQ 流控是 Broker 侧的自我保护机制。节点发现内存、磁盘或内部队列压力升高时，会降低连接、channel 或发布者的发送速度，让 Broker 有时间处理积压。",
      "流控和背压是同一条压力链路的不同层次。背压是系统级压力反馈，流控是 RabbitMQ 节点内部执行的限速动作；应用收到发布变慢、连接阻塞或 confirm 延迟升高时，应主动降速。",
      "内存水位是常见触发点。消息堆积、未确认消息过多、队列索引和连接资源都会占用内存；触发内存报警后，RabbitMQ 会限制发布者继续推高内存压力。",
      "磁盘水位也会触发保护。可用磁盘空间低于阈值时，RabbitMQ 会阻止发布更多消息，避免持久化消息、队列数据和日志把磁盘打满。",
      "发布端能感知流控信号。常见表现包括 publisher confirm 延迟升高、basic.publish 阻塞、blocked connection 通知、发布吞吐下降和客户端超时；生产者需要退避、排队、限流或降级入口请求。",
      "流控解除需要资源恢复。消费者追上积压、队列深度下降、磁盘释放、内存回落后，连接会恢复发布能力；解除后也要平滑恢复发布速率，避免瞬间反弹再次触发流控。",
      "流控并不等于消息丢失。它主要延缓发布速度，可靠发布仍要依赖 publisher confirm、持久化消息和队列、手动 ack 等机制；生产者超时重试时要保留幂等键。",
      "流控排查要分清原因。内存报警看队列堆积、unacked、连接数、channel 数和消息体大小；磁盘报警看持久化消息增长、日志、磁盘阈值和磁盘 IO；内部流控看发布速率、队列写入和消费者处理速度。",
      "常见处置包括暂停低优先级生产者、降低发布并发、扩容消费者、清理过期积压、拆分热点队列、增加磁盘容量、调整告警阈值和优化大消息。",
      "生产环境要把流控纳入发布端设计。客户端应监听 blocked/unblocked 事件，统计 confirm 延迟，设置发布超时和退避策略，并把入口限流与业务降级接到这些信号上。",
      "监控重点包括 connection state、blocked connections、publish rate、confirm latency、queue depth、messages ready、messages unacked、memory alarm、disk free alarm、disk free limit 和节点 IO。",
      "参考来源：RabbitMQ Flow Control 文档说明 Broker 内部限速行为；Memory Alarms 与 Disk Alarms 文档说明资源阈值和发布阻塞；Connections、Publishers、Monitoring 与 Reliability 文档补充连接状态、发布端信号、指标和可靠发布边界。",
    ],
