    id: "memory-alarm",
    zh: "内存水位",
    en: "Memory Alarm",
    area: "operations",
    difficulty: "medium",
    concept: "内存水位是 RabbitMQ 节点内存占用的保护阈值，超过阈值会触发资源报警并限制发布连接。",
    explanation: [
      "RabbitMQ 会给节点设置一个内存高水位。节点内存占用超过阈值时会触发 memory alarm，并通过流控限制发布连接继续写入，避免内存压力继续扩大。",
      "默认相对阈值约为可用内存的 60%。生产环境可以设置相对阈值，也可以设置绝对值；在 Kubernetes 和容器环境里，绝对阈值更稳定，因为容器可见内存和宿主机内存容易存在偏差。",
      "触发 memory alarm 后，发布者会感受到连接阻塞、confirm 延迟上升、发布吞吐下降或客户端超时。消费者继续消费并 ack，队列积压下降、内存回落后，发布能力会恢复。",
      "常见内存来源包括 ready 消息、unacked 消息、队列索引、连接和 channel、插件、Erlang VM 开销、大消息 payload，以及高并发发布造成的内部缓冲。",
      "unacked 堆积是高频诱因。消费者 prefetch 过大、处理耗时变长或 ack 卡住时，消息长期停留在未确认状态，占用内存并延迟重投递。",
      "队列积压也会推高内存压力。Classic Queue、Quorum Queue、持久化消息和大消息会有不同内存与磁盘行为；大量积压时要同时看队列深度、消息体大小、磁盘 IO 和复制开销。",
      "内存水位和磁盘水位经常一起出现。内存报警会限制发布保护 RAM，磁盘报警会限制发布保护持久化存储；排查时要同时看 memory alarm、disk free alarm、队列深度和磁盘写入。",
      "处理 memory alarm 的优先动作是让消费追上积压：扩容消费者、降低单条处理耗时、修复慢下游、调小 prefetch、清理过期消息、暂停低优先级生产者和拆分热点队列。",
      "长期治理要减少内存占用源。控制单条消息大小，避免把大文件放进消息体；使用消息 TTL 和长度限制控制堆积；让大 payload 走对象存储，只在消息中传引用。",
      "阈值配置要结合部署环境。裸机可以使用相对水位，容器建议使用 `vm_memory_high_watermark.absolute`；调整阈值只能扩大保护边界，真正恢复仍依赖消费能力和资源释放。",
      "排查命令和指标包括 `rabbitmq-diagnostics memory_breakdown`、`rabbitmq-diagnostics status`、memory used、memory alarm、messages ready、messages unacked、connection/channel 数、publish rate 和 confirm latency。",
      "参考来源：RabbitMQ Memory Alarms 文档说明阈值、默认比例、容器绝对阈值和发布阻塞行为；Flow Control、Disk Alarms、Monitoring、Queues、Consumer Prefetch、Connections 与 Reliability 文档补充流控、磁盘保护、指标、未确认消息和可靠性边界。",
    ],
