    id: "rate-limit",
    zh: "消费限速",
    en: "Consumer Rate Limit",
    area: "operations",
    difficulty: "medium",
    concept: "消费限速通过控制消费者并发、prefetch 和业务令牌桶，让消息处理速率匹配数据库、缓存和第三方服务容量。",
    explanation: [
      "消费限速的目标是保护下游。RabbitMQ 可以很快把消息推给消费者，但真正的瓶颈常在数据库连接池、缓存写入、第三方 API、CPU 或业务锁，限速让处理速度稳定在下游可承受范围内。",
      "第一层抓手是消费者实例数和线程并发。实例越多、线程越多，消费吞吐越高；下游耗时升高时，降低并发比继续扩容更能保护系统。",
      "第二层抓手是 prefetch。`basic.qos` 的 prefetch_count 限制消费者未确认消息数量，RabbitMQ 对每个消费者单独应用这个限制；它能控制 in-flight 消息，减少慢消费者长期占住任务。",
      "第三层抓手是业务限流。令牌桶、漏桶、信号量、连接池上限和租户配额可以控制单位时间处理量；访问第三方接口时，令牌桶通常要按对方配额、超时和重试预算设置。",
      "限速要和手动 ack 配套。消费者拿到消息后先获得业务令牌，处理成功再 ack；拿不到令牌时可以短暂等待、延迟重试或暂停消费，避免大量消息堆在消费者本地。",
      "消费限速和背压配合使用。消费者限速会让队列深度上升，队列积压再把压力反馈给生产端；当积压接近 SLA 或容量边界时，入口限流和生产端降速要同步开启。",
      "限速和扩缩容要一起看。consumer capacity 低、最老消息年龄升高、下游仍有余量时可以扩容消费者；下游延迟升高、错误率上升时应降速或降级。",
      "重试会放大限速压力。失败消息立即重试会占满令牌和线程，导致新消息排队；应使用退避、抖动和重试上限，把失败流量从主消费能力里隔离出来。",
      "多租户或多业务队列要做配额。大客户、低优先级任务和批处理任务可以单独队列、单独消费者池和单独令牌桶，避免挤占核心交易消息。",
      "限速参数需要动态调优。初始值可以按下游 QPS、平均耗时和目标延迟估算，再用监控指标调节；固定配置在促销高峰、慢查询和接口限额变化时容易失准。",
      "排查时看消费速率、ack 速率、处理耗时、错误率、队列深度、最老消息年龄、unacked、consumer capacity、下游连接池等待、第三方 429/5xx 和重试队列长度。",
      "参考来源：RabbitMQ Consumers 文档说明 consumer capacity 与消费者能力判断；Consumer Prefetch 文档说明 prefetch_count 的未确认消息限制；Queues、Monitoring、Reliability 与 Flow Control 文档补充队列积压、指标和压力反馈；AWS Backoff with Jitter 说明重试退避和抖动对限流稳定性的价值。",
    ],
