    id: "queue-depth",
    zh: "队列深度",
    en: "Queue Depth",
    area: "operations",
    difficulty: "easy",
    concept: "队列深度表示队列中待处理与处理中消息的积压规模，是判断延迟风险、消费能力和扩缩容时机的核心指标。",
    explanation: [
      "队列深度不是单一数字。RabbitMQ 常见口径包括 messages 总数、messages_ready 待投递消息和 messages_unacknowledged 已投递未确认消息；三者要一起看。",
      "messages_ready 高，说明消息还在队列里等待消费者获取，常见原因是消费者数量不足、消费者处理慢、队列分区不均或消费者连接异常。",
      "messages_unacknowledged 高，说明消息已经交给消费者但还没有 ack，常见原因是处理耗时长、prefetch 过大、消费者线程卡住、下游服务慢或 ack 逻辑异常。",
      "队列深度要结合速率判断。publish rate 高于 ack rate 时，积压会持续增加；ack rate 追上 publish rate 后，队列深度才会逐步下降。",
      "队列深度还要结合最老消息年龄。相同的消息数，在高吞吐短任务里可能只是瞬时波动，在低吞吐长任务里可能已经超过 SLA；最老消息年龄更能体现用户等待时间。",
      "队列深度常用于扩缩容触发。KEDA RabbitMQ scaler 可以基于队列长度或消息速率扩缩 Kubernetes 消费者，但触发前要确认下游容量仍有余量。",
      "队列深度高时优先区分瓶颈位置。ready 高偏向消费者不足或分发异常，unacked 高偏向消费者处理慢或 prefetch 配置问题，内存/磁盘水位高偏向 Broker 资源压力。",
      "顺序消费和分区队列要看每个分区深度。总深度正常也可能隐藏单个热点分区；热点队列的最老消息年龄和 key 分布比总数更有排查价值。",
      "队列深度告警要按业务分层。订单、支付、库存这类核心队列用更低延迟阈值；批处理、日志、通知队列可以使用更大的缓冲窗口和分级告警。",
      "队列深度下降也要看代价。大量消费者扩容可能让下游数据库变慢，过高 prefetch 会让 unacked 激增；健康目标是深度、延迟、错误率和下游耗时同时回稳。",
      "排查指标包括 messages、messages_ready、messages_unacknowledged、publish rate、ack rate、deliver/get rate、oldest message age、consumer count、consumer capacity、prefetch、memory、disk 和 DLQ 数量。",
      "参考来源：RabbitMQ Monitoring 文档说明 messages、ready、unacknowledged、消息速率和队列指标；Queues、Consumers 与 Consumer Prefetch 文档补充队列、消费者能力和未确认消息语义；Memory/Disk Alarms 文档说明资源水位；KEDA RabbitMQ scaler 文档补充基于队列长度和速率的扩缩容触发。",
    ],
