    id: "consumer-lag",
    zh: "消费滞后",
    en: "Consumer Lag",
    area: "operations",
    difficulty: "medium",
    concept: "消费滞后描述消息从进入队列到被业务成功处理之间的延迟，反映生产速率、消费能力和下游耗时的失衡程度。",
    explanation: [
      "消费滞后的核心是时间。队列深度告诉你有多少消息在等，消费滞后告诉你消息等了多久、用户或任务结果会晚多久。",
      "RabbitMQ 没有 Kafka offset lag 那种天然位移差，通常用最老消息年龄、队列深度、publish rate 和 ack rate 的差值、应用侧处理延迟来估算滞后。",
      "最老消息年龄最接近 SLA 风险。订单支付通知等待 30 秒和日志入库等待 30 秒含义完全不同，所以滞后告警要按业务队列配置不同阈值。",
      "速率差决定滞后趋势。publish rate 持续高于 ack rate 时，积压和等待时间会持续增加；ack rate 大于 publish rate 时，系统开始消化历史积压。",
      "ready 和 unacked 能帮助定位滞后位置。messages_ready 高表示消息还在队列里等消费者；messages_unacknowledged 高表示消息已经在消费者手里，业务处理、下游调用或 ack 路径存在压力。",
      "consumer capacity、消费者数量、prefetch 和处理耗时要一起看。consumer capacity 低且下游仍有余量时可以扩容；处理耗时和错误率升高时，扩容会把压力推给下游。",
      "重试和死信会影响滞后判断。大量失败消息反复重试会占用消费者能力，让正常消息等待变长；需要单独观察 retry queue、DLQ、redelivery rate 和错误类型。",
      "顺序消费场景要看业务键内滞后。一个热点订单、账户或租户可能拖慢单个分区，总队列滞后看起来正常，单分区最老消息年龄已经超出 SLA。",
      "自动扩缩容可以使用队列长度或消息速率，但延迟型业务还要把最老消息年龄和应用处理延迟纳入决策。只按消息数扩容会漏掉慢任务和大消息。",
      "降低滞后有几类动作：增加消费者、优化慢 SQL 或外部接口、调小过大的 prefetch、拆分热点分区、暂停低优先级生产者、调整重试退避和清理过期消息。",
      "排查指标包括 oldest message age、messages_ready、messages_unacknowledged、publish rate、ack rate、deliver/get rate、consumer capacity、处理耗时 P95/P99、错误率、redelivery rate、retry queue 和 DLQ。",
      "参考来源：RabbitMQ Monitoring 文档说明队列消息数、ready/unacknowledged、消息速率和应用处理延迟指标；Queues、Consumers 与 Consumer Prefetch 文档补充队列、消费者能力和 in-flight 语义；Reliability 与 Flow Control 文档补充重投递和压力反馈；KEDA RabbitMQ scaler 文档补充队列长度和消息速率的扩缩容触发。",
    ],
