    id: "network-partition",
    zh: "网络分区",
    en: "Network Partition",
    area: "operations",
    difficulty: "hard",
    concept: "网络分区是 RabbitMQ 集群节点之间通信中断的状态，会影响元数据、quorum queue、stream 和客户端连接的可用性与恢复路径。",
    explanation: [
      "网络分区发生在集群节点彼此通信中断时，原因可以是网络故障、防火墙变更、DNS 问题、端口阻断、虚拟机挂起恢复或宿主机迁移。它的影响取决于被隔离节点承载了哪些 Raft 组件和客户端连接。",
      "RabbitMQ 4.3 起，关键复制组件统一围绕 Raft：Khepri 元数据存储、quorum queue、stream coordinator。旧版 Mnesia 时代的 `cluster_partition_handling`、pause_minority、autoheal 等配置在 4.3+ 处于兼容保留状态，配置项无实际效果。",
      "判断分区先看节点连通性。`rabbitmq-diagnostics cluster_status` 会列出当前可达的 running nodes，被隔离节点会从可达列表中消失；相关日志会记录连接丢失、Raft leader election 和恢复过程。",
      "再看复制资源状态。`rabbitmq-queues quorum_status <queue>` 可以查看 quorum queue 的 leader 和 followers，`rabbitmq-streams stream_status <stream>` 可以查看 stream leader 和 replicas，`rabbitmq-diagnostics check_if_node_is_quorum_critical` 可以评估下线某个节点是否会让资源失去多数派。",
      "leader 所在节点失联时，多数派一侧会发起新 leader 选举。选举窗口内，quorum queue 的写入和消费投递会暂停或延迟，publisher confirm 可能延迟返回或收到 `basic.nack`。",
      "follower 所在节点失联时，多数派一侧继续提供服务。该节点恢复后会连接当前 leader，并通过 Raft 日志补齐缺失数据；中断时间越长，追赶数据量和恢复窗口越大。",
      "被隔离节点没有承载相关 quorum queue 或 stream 副本时，主要影响是集群容量和连接在该节点上的客户端。客户端需要重连到可达节点，继续执行拓扑恢复、消费者重订阅和未确认消息处理。",
      "Raft 的核心约束是在线多数派。3 个副本可以承受 1 个副本失联，5 个副本可以承受 2 个副本失联；2 个副本在单点失联后会失去多数派，所以生产复制队列通常使用奇数副本数。",
      "分区期间的消息语义要靠客户端配合。生产者使用 publisher confirms 识别已接管消息，消费者使用 manual ack 让未完成消息回队列；连接切换和确认丢失会带来重复投递，业务侧要准备幂等处理。",
      "运维处置顺序是先保护多数派，再恢复连通性。先确认集群拓扑、quorum 资源、leader 分布和客户端连接，随后检查网络、DNS、端口、Erlang distribution、节点名和证书配置。",
      "计划维护前要评估 quorum critical。滚动重启、节点替换、宿主机维护前先运行 quorum critical 检查，再确认副本分布和监控状态；连续下线多个承载副本的节点会让相关队列暂停服务。",
      "恢复后继续观察追赶过程。返回节点会从 leader 拉取缺失日志，在追赶完成前通常作为临时低可用成员处理；长时间分区后要关注磁盘、网络吞吐、confirm latency 和副本同步进度。",
      "监控指标包括 cluster reachable nodes、network partitions、quorum queue leader、online members、leader election、publisher confirms、basic.nack、redeliveries、connection churn、consumer count、memory alarm 和 disk alarm。",
      "参考来源：RabbitMQ Network Partitions 文档说明 4.3+ Raft 化后的分区影响、leader 失联、follower 失联、恢复和多数派要求；Quorum Queues 文档说明 Raft、leader/follower、复制和确认语义；Clustering、Networking、Monitoring 与 Connections 文档补充节点通信、端口、观测和客户端重连。",
    ],
