    id: "consumer-recovery",
    zh: "消费者恢复",
    en: "Consumer Recovery",
    area: "operations",
    difficulty: "medium",
    concept: "消费者恢复是在连接断开、节点切换或 Broker 重启后，重新建立连接、恢复通道和订阅，并安全处理未确认消息的流程。",
    explanation: [
      "消费者恢复的目标是让消费进程在网络抖动、节点重启、连接断开后继续工作，并把消息语义维持在可验证状态。它同时涉及客户端重连、拓扑恢复、消费者重订阅、手动确认和业务幂等。",
      "故障检测通常来自 I/O 异常、socket 读超时、心跳缺失或连接事件。心跳负责缩短故障发现时间，连接恢复负责重新连到可用节点，消费者恢复负责重新建立订阅关系。",
      "现代 RabbitMQ Java 客户端默认启用自动连接恢复和拓扑恢复。典型流程是重新连接、恢复连接监听器、重新打开 channel、恢复 channel 监听器、恢复 `basic.qos`、publisher confirm 和事务设置，然后重新声明 exchange、queue、binding 并恢复 consumers。",
      "首次建连失败由应用层重试逻辑处理，连接被应用主动关闭代表正常退出，channel 级异常通常代表声明参数、权限、队列不存在等语义问题，需要应用修正后重建 channel。",
      "拓扑恢复依赖客户端维护的连接级缓存。客户端会记录已声明的 exchange、queue、binding 和 consumer；auto-delete、exclusive queue、queue TTL、服务端生成队列名和动态删除资源会让恢复路径更复杂。",
      "消费者标签要保持唯一且稳定。重复 consumer tag 会干扰自动恢复和监控识别，恢复后应用也更难判断哪个订阅已经重新建立。",
      "手动确认是消费者恢复的关键。连接断开时，Broker 会把该连接上未确认的消息重新入队，恢复后的消费者可能再次收到同一条消息；业务处理要用 message id、业务唯一键、去重表或状态机保证幂等。",
      "delivery tag 在连接和 channel 生命周期内有效。自动恢复后底层 delivery tag 会重置，Java 客户端会做标签转换；应用仍然要处理 ack 时连接已经变化、消息已经重投递、旧回调延迟执行这类竞态。",
      "prefetch 会影响恢复冲击。prefetch 太大时，单个消费者断开会带回大量 unacked 消息，恢复后可能形成重投递洪峰；核心业务通常用较小 prefetch、并发消费者和限速来平滑恢复。",
      "消费者恢复要和高可用一起设计。客户端应配置多个地址或健康检查负载均衡，连接到新节点后重新订阅；quorum queue leader 切换期间，投递会短暂暂停，恢复后继续从可用 leader 拉取消息。",
      "监控要覆盖恢复全过程。重点看 connection churn、consumer count、consumer capacity、redeliveries、messages_unacknowledged、ack rate、处理耗时、错误率、心跳断开、恢复失败次数和应用日志中的 recovery listener 事件。",
      "排查顺序可以从连接开始：先看消费者进程是否在线，再看连接和心跳，再看 channel 异常、权限和队列声明，再看 consumer tag、prefetch、unacked、redelivery 和业务处理耗时。",
      "参考来源：RabbitMQ Java Client API Guide 说明自动连接恢复、拓扑恢复、消费者恢复、重试间隔、恢复触发条件和限制；Reliability、Connections、Consumers、Heartbeats 与 Confirms 文档补充连接故障、手动确认、重投递、心跳和可靠性语义；Consumer Prefetch 与 Monitoring 文档补充恢复冲击和观测指标。",
    ],
