    id: "work-queue",
    zh: "工作队列",
    en: "Work Queue",
    area: "pattern",
    difficulty: "easy",
    concept: "工作队列把耗时任务封装成消息放入同一个队列，由多个消费者竞争处理，用并行 worker 提升吞吐。",
    explanation: [
      "工作队列也叫任务队列，适合把耗时操作从请求线程中拆出去。生产者只负责提交任务消息，后台 worker 从队列取任务并执行，多个 worker 共享同一个队列。",
      "默认分发方式是轮询。RabbitMQ 会把消息按顺序发给下一个消费者，长期看每个消费者拿到的消息数量接近；任务耗时差异很大时，数量均衡仍可能造成负载倾斜。",
      "工作队列的可靠性从手动确认开始。消费者完成业务处理后发送 ack，Broker 才会删除消息；消费者断开、channel 关闭或 TCP 连接丢失时，未确认消息会重新入队并投递给其他消费者。",
      "忘记 ack 会让 messages_unacknowledged 持续增长，Broker 内存也会被未释放消息占用。排查时可以看队列的 messages_ready 和 messages_unacknowledged，确认消息停在队列里还是停在消费者手里。",
      "公平分发依赖 prefetch。`basic.qos(1)` 表示一个消费者一次只持有一个未确认消息，处理完并 ack 后再接收下一条；这样慢 worker 不会堆积大量任务，空闲 worker 更容易拿到新任务。",
      "prefetch 取值要按任务耗时和吞吐调节。CPU 密集或慢任务适合较小 prefetch；IO 密集、批量处理或下游延迟稳定的任务可以适当增大 prefetch，以减少往返开销。",
      "任务跨 Broker 重启保存需要两层配置：队列 durable，消息 persistent。RabbitMQ 官方教程在 4.x 示例里使用 quorum queue 作为 durable task queue，让队列本身具备复制和更强恢复能力。",
      "持久化消息也要配合 publisher confirms。生产者收到 confirm 后，才可以认为 RabbitMQ 接管了任务；只设置 persistent 仍然存在写入窗口和确认窗口，需要用 confirm 收敛风险。",
      "工作队列天然会产生重复处理场景。消费者处理成功后 ack 丢失、处理超时、进程崩溃或恢复重投递，都可能让同一任务再次执行；业务侧要用任务 ID、唯一约束、状态机或去重表保证幂等。",
      "扩容方式很直接：队列积压升高时增加 worker，消费能力不足时优化处理逻辑或拆分队列。扩容前要确认瓶颈在消费者侧，慢 SQL、外部接口限流和下游容量会限制扩容收益。",
      "工作队列适合互相独立、可重试、可幂等的任务，例如图片处理、邮件发送、报表生成、异步导入、批量计算。强顺序、强事务一致性和实时响应场景要额外设计顺序键、事务外盒或同步接口。",
      "监控重点包括 queue depth、oldest message age、messages_ready、messages_unacknowledged、deliver/ack rate、redelivery rate、consumer count、consumer capacity、任务处理耗时和错误率。",
      "参考来源：RabbitMQ Work Queues 教程说明任务队列、轮询分发、手动确认、durability、persistent message 和 fair dispatch；Queues、Consumers、Consumer Prefetch、Confirms 与 Reliability 文档补充队列语义、消费者状态、prefetch、ack/confirm 和故障恢复细节；doocs advanced-java 提供中文面试视角。",
    ],
