    id: "rpc-pattern",
    zh: "RPC 模式",
    en: "RPC Pattern",
    area: "pattern",
    difficulty: "medium",
    concept: "RPC 模式用请求队列、回复地址和 correlationId 在 RabbitMQ 上实现请求/响应调用，让客户端发送消息后等待远端处理结果。",
    explanation: [
      "RabbitMQ RPC 模式适合把一次远程计算封装成请求/响应流程。客户端发送请求消息，服务端消费请求并处理，再把结果发布回客户端指定的回复地址。",
      "基本链路包含三类对象：固定的请求队列、客户端的 callback queue 或 Direct Reply-to、以及响应消息。服务端只监听请求队列，响应投递到请求消息里的 `reply_to` 地址。",
      "客户端发送请求时会设置两个关键属性：`reply_to` 表示响应发回哪里，`correlation_id` 表示这次请求的唯一标识。客户端收到响应后用 `correlation_id` 匹配等待中的请求。",
      "callback queue 可以每个请求创建一个，也可以每个客户端复用一个。每个请求一个队列开销大；每个客户端一个队列更常见，correlationId 负责把同一队列里的多个响应匹配回各自请求。",
      "Direct Reply-to 是 RabbitMQ 的轻量替代方案。客户端消费伪队列 `amq.rabbitmq.reply-to`，请求消息把 `reply-to` 设置为该名称，服务端按返回的 reply-to 值发布响应，Broker 直接把响应送回同一连接和 channel。",
      "Direct Reply-to 减少了回复队列创建、删除、元数据和管理 API 开销，适合大量短连接或海量请求/响应客户端。它的回复语义是 at-most-once，客户端断开后响应会被丢弃，调用方需要用超时和重试处理。",
      "服务端处理请求时通常使用 manual ack。业务处理成功并成功发布响应后再 ack 请求；服务端在发送响应后、ack 请求前崩溃时，请求可能被重新投递，客户端可能收到重复响应。",
      "客户端要能忽略未知或重复 correlationId。官方教程特别强调重复响应 race：服务端发送响应后在 ack 前宕机，重启后再次处理同一请求，客户端应按 correlationId 去重并只完成一次调用。",
      "RPC 必须有超时。请求队列积压、服务端慢、响应丢失、客户端断线、Direct Reply-to 响应丢弃都会让调用等待变长；调用方要设置 deadline、超时重试、熔断和并发上限。",
      "RPC 的业务操作要尽量幂等。超时后的重试可能让服务端重复执行，响应重复也会出现；写操作需要请求 ID、唯一约束、状态机或幂等表来保护副作用。",
      "RPC 模式会把异步中间件重新包装成同步等待。它适合低频内部管理调用、短耗时计算、需要异步系统返回结果的场景；高吞吐链路通常使用事件驱动、任务队列和回调事件来降低耦合。",
      "容量设计要关注请求队列深度、响应等待数、服务端 consumer count、prefetch、处理耗时、超时率、重复响应数和 redelivery rate。服务端扩容可以提升吞吐，慢下游和长事务会继续拉高端到端延迟。",
      "参考来源：RabbitMQ RPC 教程说明 request queue、callback queue、reply_to、correlation_id、重复响应和幂等建议；Direct Reply-to 文档说明伪队列、同连接同 channel、无回复队列、at-most-once 回复和使用限制；AMQP Concepts、Queues、Consumers、Confirms 与 Reliability 文档补充消息属性、确认、队列和故障恢复语义；doocs advanced-java 提供中文面试视角。",
    ],
